import type { BankQuestion } from "@/lib/bank";

/** Computer Awareness (Computer Awareness): 500 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"comp-awareness-1","question":"Which part is called the brain of the computer?","options":["RAM","Hard disk","CPU","Monitor"],"answer":2,"explanation":"The CPU (Central Processing Unit) processes all instructions.","difficulty":"easy"},
  {"id":"comp-awareness-2","question":"1 byte is equal to:","options":["4 bits","8 bits","16 bits","1024 bits"],"answer":1,"explanation":"A byte has 8 bits.","difficulty":"easy"},
  {"id":"comp-awareness-3","question":"Which of the following is an input device?","options":["Monitor","Printer","Keyboard","Speaker"],"answer":2,"explanation":"A keyboard sends data into the computer; the others are output devices.","difficulty":"easy"},
  {"id":"comp-awareness-4","question":"Which type of memory is volatile?","options":["ROM","RAM","Hard disk","Flash drive"],"answer":1,"explanation":"RAM loses its data when power is switched off.","difficulty":"moderate"},
  {"id":"comp-awareness-5","question":"HTTP stands for:","options":["HyperText Transfer Protocol","High Transfer Text Protocol","HyperText Transmission Process","Hyper Transfer Text Program"],"answer":0,"explanation":"HTTP is the HyperText Transfer Protocol used on the web.","difficulty":"moderate"},
  {"id":"comp-awareness-6","question":"Which shortcut copies selected text in most programs?","options":["Ctrl + V","Ctrl + C","Ctrl + X","Ctrl + P"],"answer":1,"explanation":"Ctrl + C copies, Ctrl + X cuts and Ctrl + V pastes.","difficulty":"moderate"},
  {"id":"comp-awareness-7","question":"1 kilobyte (KB) equals:","options":["1000 bits","1024 bytes","1024 bits","8 bytes"],"answer":1,"explanation":"In computing, 1 KB = 2¹⁰ = 1024 bytes.","difficulty":"hard"},
  {"id":"comp-awareness-8","question":"Which of these is an operating system?","options":["MS Word","Linux","Google Chrome","Oracle"],"answer":1,"explanation":"Linux is an operating system; the others are application software.","difficulty":"hard"},
  {"id":"comp-awareness-9","question":"Which memory is the fastest?","options":["Hard disk","RAM","Cache","ROM"],"answer":2,"explanation":"Cache memory sits closest to the CPU and is faster than RAM.","difficulty":"hard"},
  {"id":"comp-awareness-10","question":"The binary equivalent of the decimal number 10 is:","options":["1001","1010","1100","1011"],"answer":1,"explanation":"10 = 8 + 2 = 1×2³ + 0×2² + 1×2¹ + 0×2⁰ = 1010.","difficulty":"very-hard"},
  {"id":"comp-awareness-11","question":"Which protocol is used to send email?","options":["HTTP","FTP","SMTP","POP3"],"answer":2,"explanation":"SMTP (Simple Mail Transfer Protocol) sends mail; POP3 and IMAP retrieve it.","difficulty":"very-hard"},
  {"id":"comp-awareness-12","question":"Which number system uses base 16?","options":["Binary","Octal","Decimal","Hexadecimal"],"answer":3,"explanation":"Hexadecimal uses 16 symbols, 0–9 and A–F.","difficulty":"very-hard"},
  {"id":"comp-awareness-13","question":"The “brain” of the computer is the:","options":["RAM","CPU","Hard disk","Monitor"],"answer":1,"explanation":"The Central Processing Unit executes instructions.","difficulty":"easy","source":"IBPS Clerk · RRB NTPC"},
  {"id":"comp-awareness-14","question":"Which of these is an output device?","options":["Keyboard","Mouse","Printer","Scanner"],"answer":2,"explanation":"A printer outputs; keyboard, mouse and scanner are input devices.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk"},
  {"id":"comp-awareness-15","question":"1 gigabyte (GB) equals:","options":["1,024 KB","1,024 MB","1,024 TB","1,000 bytes"],"answer":1,"explanation":"KB → MB → GB → TB, each 1,024 times the previous.","difficulty":"moderate","source":"IBPS PO · SBI Clerk"},
  {"id":"comp-awareness-16","question":"In MS Excel, the shortcut key to save a workbook is:","options":["Ctrl + P","Ctrl + S","Ctrl + V","Ctrl + N"],"answer":1,"explanation":"Ctrl + S saves; Ctrl + P prints; Ctrl + N opens a new file.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"comp-awareness-17","question":"Which memory is volatile, losing its contents when power is switched off?","options":["ROM","RAM","Hard disk","Flash drive"],"answer":1,"explanation":"RAM is volatile; ROM and disks keep data without power.","difficulty":"hard","source":"IBPS PO · SSC CHSL"},
  {"id":"comp-awareness-18","question":"The protocol used to send e-mail from a client to a mail server is:","options":["HTTP","FTP","SMTP","POP3"],"answer":2,"explanation":"SMTP sends mail; POP3/IMAP retrieve it.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"comp-awareness-19","question":"Which of these is NOT an operating system?","options":["Linux","Windows","Oracle Database","macOS"],"answer":2,"explanation":"Oracle Database is a database management system.","difficulty":"hard"},
  {"id":"comp-awareness-20","question":"The hexadecimal number 1F equals which decimal number?","options":["15","31","30","16"],"answer":1,"explanation":"1F = 1 × 16 + 15 = 31.","difficulty":"hard"},
  {"id":"comp-awareness-21","question":"Which layer of the OSI model handles routing of packets between networks?","options":["Data link","Network","Transport","Session"],"answer":1,"explanation":"The network layer (layer 3) routes packets using IP addresses.","difficulty":"very-hard"},
  {"id":"comp-awareness-22","question":"Which order lists memory from fastest to slowest?","options":["Registers, cache, RAM, hard disk","Cache, registers, RAM, hard disk","RAM, cache, registers, hard disk","Registers, RAM, cache, hard disk"],"answer":0,"explanation":"Registers sit inside the CPU, then cache, then main memory, then storage.","difficulty":"very-hard"},
  {"id":"comp-awareness-23","question":"How many of these statements are correct? I. One byte is eight bits. II. A nibble is four bits. III. ROM is volatile memory. IV. Cache memory sits between the CPU and the main memory.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. ROM keeps its contents without power.","difficulty":"very-hard"},
  {"id":"comp-awareness-24","question":"How many of these statements are correct? I. HTTP uses port 80 by default. II. HTTPS uses port 443 by default. III. FTP is the protocol used to send e-mail.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. E-mail is sent with SMTP; FTP transfers files.","difficulty":"very-hard"},
  {"id":"comp-awareness-25","question":"How many of these statements are correct? I. RAM is volatile memory. II. Cache memory is faster than RAM. III. ROM loses its contents when the power is switched off.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. ROM is non-volatile and keeps its contents without power.","difficulty":"very-hard"},
  {"id":"comp-awareness-26","question":"What is the binary number 101101 in decimal?","options":["45","43","47","53"],"answer":0,"explanation":"32 + 0 + 8 + 4 + 0 + 1 = 45.","difficulty":"very-hard"},
  {"id":"comp-awareness-27","question":"Which layer of the OSI model routes packets between networks?","options":["Network layer","Transport layer","Data link layer","Session layer"],"answer":0,"explanation":"The network layer (layer 3) handles logical addressing and routing; IP works here.","difficulty":"very-hard"},
  {"id":"comp-awareness-28","question":"What is the sum of the hexadecimal number 2A and the binary number 1011, written in decimal?","options":["53","51","47","55"],"answer":0,"explanation":"2A = 2 × 16 + 10 = 42 and 1011 = 8 + 2 + 1 = 11, so the sum is 53.","difficulty":"very-hard","source":"IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-29","question":"How many of these statements are correct? I. A compiler translates a whole program at once, while an interpreter translates it line by line. II. Linux is an open-source operating system. III. A firewall is used to block unauthorised access to a network. IV. Standard ASCII uses 16 bits for each character.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Standard ASCII is a 7-bit code (128 characters), stored in 8-bit bytes; Unicode UTF-16 uses 16 bits.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk"},
  {"id":"comp-awareness-30","question":"URL stands for:","options":["Uniform Resource Locator","Universal Reference Link","Unified Resource Link","Universal Resource Language"],"answer":0,"explanation":"A URL (Uniform Resource Locator) is the address of a resource on the web, such as https://example.com/page.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-31","question":"In MS Word, the shortcut key to make selected text bold is:","options":["Ctrl + I","Ctrl + B","Ctrl + U","Ctrl + D"],"answer":1,"explanation":"Ctrl + B is bold, Ctrl + I italic and Ctrl + U underline.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-32","question":"WWW stands for:","options":["World Web Wire","Wide World Web","World Wide Web","World Wide Wire"],"answer":2,"explanation":"The World Wide Web, invented by Tim Berners-Lee in 1989, is the system of linked hypertext documents accessed over the internet.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-33","question":"Which generation of computers was based on transistors?","options":["First","Second","Third","Fourth"],"answer":1,"explanation":"First generation used vacuum tubes, second transistors, third integrated circuits and fourth microprocessors.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-34","question":"Which of these is a non-volatile storage device?","options":["RAM","Cache memory","Hard disk","CPU registers"],"answer":2,"explanation":"A hard disk keeps data when power is off; RAM, cache and registers are volatile and lose their contents.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-35","question":"The smallest unit of data in a computer is a:","options":["Byte","Nibble","Bit","Word"],"answer":2,"explanation":"A bit (binary digit) is 0 or 1; a nibble is 4 bits and a byte 8 bits.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-36","question":"Which of the following is application software?","options":["Windows 11","Linux","MS Excel","Device driver"],"answer":2,"explanation":"MS Excel is an application used for a specific task (spreadsheets); operating systems and device drivers are system software.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-37","question":"In MS Excel, the cell address B3 refers to:","options":["Row B, column 3","Column B, row 3","The third sheet","Block 3"],"answer":1,"explanation":"Excel addresses cells by column letter followed by row number, so B3 is the cell in column B and row 3.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-38","question":"The device that lets a computer send digital data over a telephone line is a:","options":["Router","Modem","Switch","Repeater"],"answer":1,"explanation":"A modem (modulator–demodulator) converts digital signals to analogue for the telephone line and back again.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-39","question":"The octal equivalent of the binary number 110101 is:","options":["53","65","35","71"],"answer":1,"explanation":"Group the bits in threes from the right: 110 101 → 6 5, so 110101₂ = 65₈ (= 53 in decimal).","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-40","question":"Which protocol automatically assigns IP addresses to devices on a network?","options":["DNS","FTP","DHCP","SMTP"],"answer":2,"explanation":"The Dynamic Host Configuration Protocol leases IP addresses to devices; DNS resolves names, FTP transfers files and SMTP sends mail.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-41","question":"An IPv4 address is how many bits long?","options":["16 bits","32 bits","64 bits","128 bits"],"answer":1,"explanation":"IPv4 uses 32-bit addresses written as four octets (e.g. 192.168.1.1); IPv6 uses 128-bit addresses.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-42","question":"Cache memory in a computer is typically built from:","options":["DRAM","SRAM","EEPROM","Magnetic cores"],"answer":1,"explanation":"Cache uses static RAM, which is faster (no refresh needed) but costlier than the dynamic RAM used for main memory.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-43","question":"The hexadecimal equivalent of the decimal number 255 is:","options":["FF","EE","F0","100"],"answer":0,"explanation":"255 = 15 × 16 + 15, and 15 is F in hexadecimal, so 255 = FF₁₆; 100₁₆ would be 256.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-44","question":"Which program translates assembly language into machine code?","options":["Compiler","Interpreter","Assembler","Loader"],"answer":2,"explanation":"An assembler converts mnemonic assembly instructions into machine code; compilers and interpreters work on high-level languages.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-45","question":"The default port number used by FTP for control connections is:","options":["20","21","23","25"],"answer":1,"explanation":"FTP uses port 21 for commands (and 20 for data); Telnet uses 23 and SMTP 25.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-46","question":"In which network topology are all nodes connected to a central hub or switch?","options":["Bus","Ring","Star","Mesh"],"answer":2,"explanation":"In a star topology each device has its own link to a central device, so one cable failure does not bring down the whole network.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-47","question":"The Domain Name System (DNS) is used to:","options":["Encrypt web traffic","Translate domain names into IP addresses","Assign MAC addresses","Compress web pages"],"answer":1,"explanation":"DNS maps human-readable names such as example.com to numeric IP addresses that routers use.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-48","question":"How many of these statements about computer generations are correct? I. First-generation computers used vacuum tubes. II. Second-generation computers used integrated circuits. III. Fourth-generation computers use microprocessors. IV. The fifth generation is associated with artificial intelligence.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. II is wrong: second-generation machines used transistors; integrated circuits mark the third generation.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-49","question":"Assertion (A): Cache memory makes the CPU work faster. Reason (R): Cache keeps frequently used data and instructions close to the CPU, so fewer slow accesses to main memory are needed.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Cache hits avoid the long wait for main memory, so the processor spends less time idle; R is the mechanism behind A.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-50","question":"Match the protocol with its default port: 1. SMTP 2. HTTP 3. HTTPS 4. DNS; a. 443 b. 53 c. 80 d. 25","options":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-d, 2-a, 3-c, 4-b","1-b, 2-c, 3-a, 4-d"],"answer":0,"explanation":"SMTP uses port 25, HTTP 80, HTTPS 443 and DNS 53.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-51","question":"How many bits are there in 2 KB of data (1 KB = 1024 bytes)?","options":["2,048","8,192","16,384","20,480"],"answer":2,"explanation":"2 KB = 2 × 1024 = 2,048 bytes = 2,048 × 8 = 16,384 bits.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-52","question":"Which of the following is NOT an input device?","options":["Light pen","Joystick","Plotter","Scanner"],"answer":2,"explanation":"A plotter draws output on paper; light pens, joysticks and scanners feed data into the computer.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-53","question":"How many of these statements are correct? I. The TCP/IP model has four layers. II. ARPANET, the forerunner of the internet, began in 1969. III. HTML is a programming language. IV. Tim Berners-Lee proposed the World Wide Web in 1989.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: HTML is a markup language that describes page structure; it has no logic or control flow of its own.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-54","question":"Arrange these programming languages in the order they appeared, earliest first: 1. Java 2. COBOL 3. FORTRAN 4. C","options":["3, 2, 4, 1","2, 3, 4, 1","3, 4, 2, 1","2, 3, 1, 4"],"answer":0,"explanation":"FORTRAN (1957) → COBOL (1959) → C (1972) → Java (1995).","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-55","question":"Assertion (A): The BIOS of a computer is stored in ROM. Reason (R): ROM retains its contents even when the power is switched off.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Start-up firmware must survive power-off so the machine can boot, which is why it lives in non-volatile ROM (flash) rather than RAM.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-56","question":"Match the MS Word shortcut with its function: 1. Ctrl + Z 2. Ctrl + Y 3. Ctrl + U 4. Ctrl + P; a. Print b. Underline c. Redo d. Undo","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":0,"explanation":"Ctrl + Z undo, Ctrl + Y redo, Ctrl + U underline, Ctrl + P print.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-57","question":"How many of these statements are correct? I. The Linux kernel was created by Linus Torvalds. II. An operating system is a type of application software. III. Python is an interpreted language. IV. Open-source software must always be distributed free of cost.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong (an OS is system software) and IV is wrong: open source means the source code is available under a licence; it may still be sold.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-58","question":"Which of the following numbers has the largest value?","options":["1F in hexadecimal","11111 in binary","37 in octal","32 in decimal"],"answer":3,"explanation":"1F₁₆ = 31, 11111₂ = 31 and 37₈ = 3 × 8 + 7 = 31, so 32 in decimal is the largest.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-59","question":"Which pair of term and description is NOT correctly matched?","options":["Phishing – fraudulent messages that trick users into revealing passwords","Trojan – malware disguised as a legitimate program","Worm – malware that needs a host file to spread","Firewall – system that filters network traffic"],"answer":2,"explanation":"A worm is self-replicating and spreads on its own across networks; it is a virus that attaches itself to a host file or program.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id": "comp-awareness-60", "question": "In MS Word, which shortcut selects all the text in a document?", "options": ["Ctrl + S", "Ctrl + A", "Ctrl + L", "Ctrl + E"], "answer": 1, "explanation": "Ctrl + A selects all. Ctrl + S saves, Ctrl + L left-aligns and Ctrl + E centres the text.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-61", "question": "PDF, a common file format for documents, stands for:", "options": ["Printable Document File", "Public Data Format", "Portable Document Format", "Personal Document Folder"], "answer": 2, "explanation": "Portable Document Format was developed by Adobe so that a document looks the same on any device or operating system.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "comp-awareness-62", "question": "Which of the following is a web browser?", "options": ["MS Excel", "Mozilla Firefox", "Oracle", "Python"], "answer": 1, "explanation": "Firefox, Chrome, Edge and Safari are browsers. Excel is a spreadsheet, Oracle a database and Python a programming language.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-63", "question": "In Windows, which key combination opens the Task Manager directly?", "options": ["Ctrl + Alt + Tab", "Alt + F4", "Ctrl + Shift + Esc", "Windows + D"], "answer": 2, "explanation": "Ctrl + Shift + Esc opens Task Manager straight away. Alt + F4 closes the active window and Windows + D shows the desktop.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-64", "question": "In MS Excel, every formula must begin with the symbol:", "options": ["+", "#", "@", "="], "answer": 3, "explanation": "Typing = tells Excel that what follows is a formula, e.g. =SUM(A1:A5). Without it the entry is treated as text or a number.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-65", "question": "Which device connects different networks and forwards data packets between them using IP addresses?", "options": ["Hub", "Repeater", "Router", "Switch"], "answer": 2, "explanation": "A router works at the network layer and chooses paths between networks. A switch connects devices within one network using MAC addresses.", "difficulty": "moderate", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-66", "question": "In most Windows programs, which function key opens Help?", "options": ["F1", "F2", "F5", "F12"], "answer": 0, "explanation": "F1 opens Help. F2 renames a selected file, F5 refreshes, and F12 opens Save As in MS Office.", "difficulty": "moderate", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "comp-awareness-67", "question": "The octal number 17 is equal to which decimal number?", "options": ["17", "15", "13", "7"], "answer": 1, "explanation": "17 in octal = 1 × 8 + 7 = 15 in decimal.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-68", "question": "Which protocol provides secure, encrypted remote login to another computer?", "options": ["Telnet", "SSH", "FTP", "SNMP"], "answer": 1, "explanation": "SSH (Secure Shell, port 22) encrypts the session. Telnet does the same job but sends everything, including passwords, as plain text.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-69", "question": "In MS Excel, which function counts only the cells in a range that contain numbers?", "options": ["COUNTA", "COUNT", "SUM", "COUNTBLANK"], "answer": 1, "explanation": "COUNT counts numeric cells only. COUNTA counts all non-empty cells, including text, and COUNTBLANK counts empty cells.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-70", "question": "Which type of memory must be refreshed thousands of times a second to keep its data?", "options": ["SRAM", "DRAM", "ROM", "Flash memory"], "answer": 1, "explanation": "DRAM stores each bit as charge on a tiny capacitor that leaks, so it needs constant refreshing. SRAM uses flip-flops and needs no refresh, which is why it is faster and used for cache.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-71", "question": "Virtual memory in a computer is:", "options": ["Memory built into the CPU registers", "A part of the hard disk used as an extension of RAM", "A type of ROM chip", "Memory available only on cloud servers"], "answer": 1, "explanation": "When RAM is full, the operating system moves less-used pages to a space on the disk (page file or swap), letting programs use more memory than is physically present, but more slowly.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-72", "question": "A CAPTCHA on a website is used to:", "options": ["Speed up page loading", "Tell human users apart from automated bots", "Encrypt passwords", "Store browsing history"], "answer": 1, "explanation": "CAPTCHA stands for Completely Automated Public Turing test to tell Computers and Humans Apart; it blocks automated sign-ups and spam.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-73", "question": "Spooling is most commonly used in computers for:", "options": ["Compressing files", "Queuing print jobs so that the CPU need not wait for the printer", "Scanning for viruses", "Defragmenting the hard disk"], "answer": 1, "explanation": "Spooling (Simultaneous Peripheral Operations On-Line) places jobs in a buffer on disk so that a slow device like a printer can take them one by one while the CPU continues working.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-74", "question": "The binary equivalent of the decimal number 156 is:", "options": ["10011100", "10011010", "11001100", "10101100"], "answer": 0, "explanation": "156 = 128 + 16 + 8 + 4, so the bits for 128, 16, 8 and 4 are 1: 10011100.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-75", "question": "How many files of 4 MB each can be stored on a 2 GB pen drive? (1 GB = 1024 MB)", "options": ["500", "512", "256", "2048"], "answer": 1, "explanation": "2 GB = 2 × 1024 = 2048 MB. 2048 ÷ 4 = 512 files. 500 is the trap of taking 1 GB as 1000 MB.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-76", "question": "How many of these statements are correct? I. A MAC address is 48 bits long. II. A switch works at the data link layer of the OSI model. III. A hub sends incoming data only to the intended device. IV. Bluetooth is an example of a personal area network technology.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. A hub broadcasts data to every port; it is the switch that forwards data only to the intended device.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-77", "question": "Assertion (A): Phishing e-mails often contain links to fake websites that look like real bank sites. Reason (R): Phishing aims to steal sensitive data such as passwords and card details by pretending to be a trusted organisation.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The fake site is the tool used to trick users into entering their details, so R explains A.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-78", "question": "Assertion (A): Data stored in RAM is lost when the power is switched off. Reason (R): RAM is made of magnetic disks.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: RAM is volatile. R is false: RAM is made of semiconductor chips; magnetic disks are used in hard disk drives, which keep data without power.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-79", "question": "Match the MS Word shortcut with its function: 1. Ctrl + F 2. Ctrl + H 3. Ctrl + K 4. Ctrl + N; a. New document b. Insert hyperlink c. Find d. Replace", "options": ["1-c, 2-b, 3-d, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-a, 4-b"], "answer": 1, "explanation": "Ctrl + F finds text, Ctrl + H opens Find and Replace, Ctrl + K inserts a hyperlink and Ctrl + N opens a new document.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-80", "question": "Match the malware with its description: 1. Trojan 2. Ransomware 3. Spyware 4. Keylogger; a. Records the keys a user presses b. Encrypts files and demands payment c. Pretends to be useful, legitimate software d. Secretly collects information about the user", "options": ["1-c, 2-b, 3-d, 4-a", "1-b, 2-c, 3-d, 4-a", "1-c, 2-d, 3-b, 4-a", "1-c, 2-b, 3-a, 4-d"], "answer": 0, "explanation": "A Trojan hides inside apparently genuine software, ransomware locks files for ransom, spyware watches the user and a keylogger records keystrokes (often to steal passwords).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-81", "question": "Which of the following is NOT a valid IPv4 address?", "options": ["10.0.0.1", "172.16.254.1", "192.168.1.256", "8.8.8.8"], "answer": 2, "explanation": "Each of the four octets in an IPv4 address is 8 bits, so it can range only from 0 to 255. 256 is out of range.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-82", "question": "Arrange in chronological order of first release: 1. Windows 95 2. MS-DOS 3. Android 4. Linux kernel", "options": ["2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 3, 1", "2, 4, 1, 3"], "answer": 3, "explanation": "MS-DOS 1981 → Linux kernel 1991 → Windows 95 in 1995 → first commercial Android phone 2008.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "comp-awareness-83", "question": "How many of these statements about MS Excel (2007 and later) are correct? I. $A$1 is an absolute cell reference. II. A worksheet has 1,048,576 rows. III. The last column of a worksheet is XFD. IV. The AVERAGE function ignores text in a range of cells.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: a sheet has 1,048,576 rows and 16,384 columns (A to XFD), and AVERAGE skips text and empty cells in a referenced range.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-84", "question": "Ignoring overheads, how long does it take to download a 100 MB file on an 8 Mbps connection? (1 byte = 8 bits)", "options": ["12.5 seconds", "100 seconds", "800 seconds", "1 second"], "answer": 1, "explanation": "100 MB = 800 megabits. Time = 800 ÷ 8 = 100 s. 12.5 s is the trap of not converting bytes to bits.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-85", "question": "Who is known as the ‘father of the computer’ for designing the Analytical Engine?", "options": ["John von Neumann", "Blaise Pascal", "Charles Babbage", "Alan Turing"], "answer": 2, "explanation": "Charles Babbage designed the Difference Engine and the programmable Analytical Engine in the 19th century. Pascal built an early mechanical calculator, and Turing laid the theoretical foundations of computing.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-86", "question": "In MS PowerPoint, which key starts the slide show from the first slide?", "options": ["F12", "F1", "F7", "F5"], "answer": 3, "explanation": "F5 starts the show from the beginning and Shift + F5 from the current slide. F1 opens Help, F7 runs the spelling check and F12 opens Save As.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-87", "question": "In e-mail, ‘BCC’ stands for:", "options": ["Bulk Copy Command", "Backup Carbon Copy", "Blind Carbon Copy", "Basic Carbon Copy"], "answer": 2, "explanation": "Addresses in the BCC field receive the message but are hidden from all other recipients, unlike addresses in the To and CC fields.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-88", "question": "Which logic gate is called a ‘universal gate’ because any other gate can be built from it alone?", "options": ["AND", "NAND", "OR", "XOR"], "answer": 1, "explanation": "NAND (and also NOR) is universal: NOT, AND and OR can all be made using only NAND gates. AND, OR and XOR cannot do this on their own.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-89", "question": "Which character-encoding standard is designed to represent the characters of almost all the world’s writing systems, including Devanagari?", "options": ["ASCII", "BCD", "Unicode", "EBCDIC"], "answer": 2, "explanation": "Unicode assigns a unique code point to over a hundred thousand characters from scripts worldwide. ASCII covers only 128 basic Latin characters, and EBCDIC is an old IBM code.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-90", "question": "In database systems, SQL stands for:", "options": ["System Query Library", "Standard Question Language", "Sequential Query Logic", "Structured Query Language"], "answer": 3, "explanation": "SQL is the standard language for creating, querying and updating relational databases, with commands such as SELECT, INSERT, UPDATE and DELETE.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-91", "question": "Moore’s law, stated by Gordon Moore, predicts that:", "options": ["Hard disk size grows tenfold every decade", "Computer prices halve every year", "The number of transistors on a chip doubles about every two years", "Internet speed doubles every six months"], "answer": 2, "explanation": "In 1965 Moore observed that transistor counts were doubling regularly, later revised to about every two years; this trend drove the rapid rise in computing power.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-92", "question": "A file with the extension .xlsx is created by default in:", "options": ["MS Access", "MS Excel", "MS PowerPoint", "MS Word"], "answer": 1, "explanation": ".xlsx is the default workbook format of Excel 2007 and later. Word uses .docx, PowerPoint .pptx and Access .accdb.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-93", "question": "The IEEE 802.11 family of standards defines:", "options": ["Ethernet (wired LAN)", "Bluetooth", "Wi-Fi (wireless LAN)", "USB"], "answer": 2, "explanation": "IEEE 802.11 covers wireless LANs, marketed as Wi-Fi. Wired Ethernet is IEEE 802.3, and Bluetooth was originally standardised as IEEE 802.15.1.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-94", "question": "The 4-bit two’s complement of the binary number 0101 is:", "options": ["1101", "1010", "0110", "1011"], "answer": 3, "explanation": "Two’s complement = one’s complement + 1: invert 0101 to 1010 and add 1 to get 1011, which represents −5. Stopping at 1010 gives only the one’s complement.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-95", "question": "Which MS Excel function looks for a value in the first column of a table and returns a value from another column in the same row?", "options": ["INDEX", "MATCH", "VLOOKUP", "HLOOKUP"], "answer": 2, "explanation": "VLOOKUP searches vertically down the first column; HLOOKUP searches along the first row. MATCH returns only the position of a value, and INDEX returns the value at a given position.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-96", "question": "Which of the following is an example of Software as a Service (SaaS)?", "options": ["Google App Engine", "A company’s own on-premises server", "Google Docs", "Amazon EC2 virtual machines"], "answer": 2, "explanation": "With SaaS the user simply uses a finished application in the browser, such as Google Docs or Gmail. EC2 rents raw computing (IaaS) and App Engine gives a platform for building apps (PaaS).", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-97", "question": "In a CPU, the program counter holds:", "options": ["The result of the last calculation", "The address of the next instruction to be fetched", "The number of programs being run", "The instruction now being decoded"], "answer": 1, "explanation": "After each fetch the program counter is updated to point to the next instruction. The instruction being decoded sits in the instruction register, and results go to the accumulator or other registers.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-98", "question": "PARAM 8000, India’s first supercomputer, was built in 1991 by:", "options": ["BARC", "C-DAC", "ISRO", "IIT Bombay"], "answer": 1, "explanation": "The Centre for Development of Advanced Computing, Pune, built PARAM 8000 under Vijay Bhatkar after India was denied a Cray supercomputer. Later PARAM systems continue the series.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-99", "question": "Restarting a computer that is already switched on, for example with the Restart option or Ctrl + Alt + Del, is called:", "options": ["Warm booting", "Hibernation", "Cold booting", "Formatting"], "answer": 0, "explanation": "Warm (soft) booting reloads the operating system without cutting the power. Cold booting starts the computer from a fully switched-off state.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-100", "question": "Which of the following is a private IPv4 address that cannot be routed on the public internet?", "options": ["11.0.0.1", "192.168.10.5", "172.32.0.1", "8.8.8.8"], "answer": 1, "explanation": "The private ranges are 10.0.0.0–10.255.255.255, 172.16.0.0–172.31.255.255 and 192.168.0.0–192.168.255.255. 172.32.0.1 lies just outside the 172 range, and 8.8.8.8 is Google’s public DNS server.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-101", "question": "Software that is distributed free for a trial period, after which the user is expected to pay for it, is called:", "options": ["Firmware", "Open-source software", "Shareware", "Freeware"], "answer": 2, "explanation": "Shareware is ‘try before you buy’. Freeware is free with no payment expected, open-source software makes its source code available, and firmware is software stored in hardware such as ROM.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-102", "question": "A digital signature on an electronic document mainly ensures:", "options": ["That the document cannot be printed", "The identity of the signer and that the document has not been altered", "That the document is compressed", "That the document is encrypted so nobody else can read it"], "answer": 1, "explanation": "A digital signature uses the signer’s private key, and anyone can check it with the public key; it gives authenticity, integrity and non-repudiation but does not by itself keep the content secret.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-103", "question": "How many of these statements about logic gates are correct? I. NOR is a universal gate. II. The output of an XOR gate is 1 when its two inputs are different. III. A NOT gate has two inputs. IV. The output of an AND gate is 1 only when all its inputs are 1.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. III is wrong: a NOT gate (inverter) has a single input whose value it reverses.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-104", "question": "The product of the binary numbers 1011 and 101 is:", "options": ["110111", "111011", "101101", "110011"], "answer": 0, "explanation": "1011 = 11 and 101 = 5 in decimal; 11 × 5 = 55 = 32 + 16 + 4 + 2 + 1 = 110111 in binary.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-105", "question": "Match the database term with its meaning: 1. Primary key 2. Foreign key 3. Tuple 4. Attribute; a. A column of a table b. A row of a table c. A field that refers to the primary key of another table d. A field that uniquely identifies each record", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-b, 3-c, 4-a", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "A primary key uniquely identifies each record; a foreign key links to another table’s primary key; in relational terms a tuple is a row (record) and an attribute is a column (field).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-106", "question": "Assertion (A): A solid-state drive (SSD) usually reads and writes data much faster than a hard disk drive (HDD). Reason (R): An SSD stores data in flash memory chips and has no moving parts.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "An HDD must spin its platters and move a read–write head to the data, while an SSD reaches any location electronically, so access is far faster. R explains A.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-107", "question": "Arrange in chronological order: 1. Release of the IBM Personal Computer 2. Founding of Google 3. Unveiling of ENIAC 4. Tim Berners-Lee’s proposal for the World Wide Web", "options": ["1, 3, 4, 2", "3, 4, 1, 2", "3, 1, 2, 4", "3, 1, 4, 2"], "answer": 3, "explanation": "ENIAC was unveiled in 1946, the IBM PC came out in 1981, the World Wide Web was proposed in 1989 and Google was founded in 1998.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-108", "question": "An uncompressed image of 1024 × 768 pixels uses 24-bit colour. Its size is (1 MB = 1024 × 1024 bytes):", "options": ["0.75 MB", "2.25 MB", "18 MB", "24 MB"], "answer": 1, "explanation": "Each pixel needs 24 bits = 3 bytes. Size = 1024 × 768 × 3 = 2,359,296 bytes = 2,359,296 ÷ 1,048,576 = 2.25 MB. Forgetting to convert bits to bytes gives 18 MB.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-109", "question": "How many of these statements about e-mail are correct? I. Recipients in the CC field are visible to all other recipients. II. Recipients in the BCC field are hidden from the other recipients. III. By default, IMAP downloads messages and deletes them from the server. IV. POP3 is the protocol used to send e-mail.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. IMAP keeps mail on the server and syncs it across devices; downloading and deleting is typical of POP3, which is a protocol for receiving mail. Mail is sent with SMTP.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-110", "question": "Which of the following is NOT a function of an operating system?", "options": ["Compiling a program’s source code into machine code", "Memory management", "Scheduling processes on the CPU", "Managing files and folders"], "answer": 0, "explanation": "Compiling is done by a compiler, a separate language translator. The operating system manages memory, processes, files, devices and security.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-111", "question": "The hexadecimal number 3A is equal to which octal number?", "options": ["72", "71", "112", "58"], "answer": 0, "explanation": "3A₁₆ = 3 × 16 + 10 = 58 in decimal; 58 = 7 × 8 + 2, so it is 72 in octal. 58 is the decimal value, the usual trap.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-112", "question": "Assertion (A): Hexadecimal notation is widely used to write binary data such as memory addresses compactly. Reason (R): Each hexadecimal digit corresponds to exactly four binary digits.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because 16 = 2⁴, every group of four bits maps to one hex digit, so a 32-bit address fits in 8 hex digits and conversion is trivial. R explains A.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-113", "question": "How many of these statements about cyber security are correct? I. A firewall can be implemented in hardware or in software. II. Two-factor authentication combines two different kinds of proof, such as a password and an OTP. III. In symmetric-key encryption the same key is used to encrypt and decrypt. IV. HTTPS sends data over the network as plain text.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: HTTPS encrypts traffic using TLS; it is plain HTTP that sends data as readable text.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-114", "question": "Match the MS Excel function with what it does: 1. SUMIF 2. CONCAT 3. TRIM 4. NOW; a. Returns the current date and time b. Removes extra spaces from text c. Joins several text strings into one d. Adds the cells that meet a given condition", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a"], "answer": 2, "explanation": "SUMIF adds cells that meet a condition, CONCAT joins text, TRIM leaves only single spaces between words, and NOW returns the current date and time (TODAY returns only the date).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"comp-awareness-115","question":"Which generation of computers used integrated circuits (ICs) as the main electronic component?","options":["Fifth generation","First generation","Second generation","Third generation"],"answer":3,"explanation":"Third-generation computers (mid-1960s to early 1970s) used ICs. The first used vacuum tubes, the second transistors, and the fourth microprocessors (VLSI).","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-116","question":"A device that works at the Data Link layer and forwards frames only to the port where the destination MAC address is connected is a:","options":["Hub","Switch","Repeater","Modem"],"answer":1,"explanation":"A switch learns MAC addresses and forwards each frame to the right port. A hub simply repeats every signal to all ports (Physical layer), as does a repeater.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-117","question":"How many layers does the OSI reference model have?","options":["7","4","5","6"],"answer":0,"explanation":"The OSI model has 7 layers: Physical, Data Link, Network, Transport, Session, Presentation and Application. The TCP/IP model is the one usually described with 4 layers.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-118","question":"Which of the following storage units is the largest?","options":["1 Gigabyte","1 Terabyte","1 Petabyte","1000 Megabytes"],"answer":2,"explanation":"Order: MB < GB < TB < PB. 1 PB = 1024 TB, so it is the largest; 1000 MB is less than 1 GB.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-119","question":"What is the decimal value of the binary number 1101.101?","options":["13.625","13.5","11.625","13.75"],"answer":0,"explanation":"1101 = 8+4+0+1 = 13; .101 = 1/2 + 0/4 + 1/8 = 0.625. Total 13.625. 13.75 would be .110.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-120","question":"Convert (777)₈ into base 10.","options":["777","511","512","448"],"answer":1,"explanation":"7×64 + 7×8 + 7 = 448 + 56 + 7 = 511. It is one less than 8³ = 512, just as 999 is one less than 10³.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-121","question":"Which Boolean expression is equal to A + A·B?","options":["A·B","B","A","A + B"],"answer":2,"explanation":"By the absorption law, A + AB = A(1 + B) = A·1 = A. A + B would come from A + A'B, a different expression.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-122","question":"A logic gate gives output 1 only when its two inputs are different. The gate is:","options":["OR","XNOR","NAND","XOR"],"answer":3,"explanation":"XOR (exclusive OR) is 1 for inputs 01 and 10. XNOR is its complement (1 when inputs are equal); OR is also 1 for input 11.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-123","question":"In the OSI model, encryption, compression and translation of data formats are functions of which layer?","options":["Transport layer","Session layer","Application layer","Presentation layer"],"answer":3,"explanation":"The Presentation layer (layer 6) handles data representation: translation, encryption and compression. The Session layer manages dialogue/sessions; the Transport layer handles end-to-end delivery.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-124","question":"Standard ASCII uses how many bits to represent a character, and so how many characters can it represent?","options":["16 bits, 65,536 characters","8 bits, 256 characters","7 bits, 128 characters","6 bits, 64 characters"],"answer":2,"explanation":"Standard ASCII is a 7-bit code with 2⁷ = 128 characters. 8-bit/256 describes 'extended ASCII', a common trap.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-125","question":"A single-layer, single-sided DVD has a standard capacity of about:","options":["700 MB","4.7 GB","25 GB","8.5 GB"],"answer":1,"explanation":"A single-layer DVD stores about 4.7 GB. 700 MB is a CD, 25 GB a single-layer Blu-ray disc, and 8.5 GB a dual-layer DVD.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-126","question":"In the IPv4 address 127.0.0.1, the address refers to:","options":["The loopback address of the local computer itself","The default gateway of the network","A public web server","The broadcast address of a class A network"],"answer":0,"explanation":"The 127.0.0.0/8 block is reserved for loopback; 127.0.0.1 ('localhost') points back to the same machine. It is never a gateway or public address.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-127","question":"What is the 8-bit two's complement representation of −5?","options":["10000101","11111010","11111011","00000101"],"answer":2,"explanation":"+5 = 00000101; one's complement = 11111010; add 1 → 11111011. 11111010 is only the one's complement, and 10000101 is the sign-magnitude form.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-128","question":"The hexadecimal number ABC is equal to which decimal number?","options":["2478","2748","2740","3020"],"answer":1,"explanation":"A=10, B=11, C=12: 10×256 + 11×16 + 12 = 2560 + 176 + 12 = 2748.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-129","question":"The decimal fraction 0.375 written in binary is:","options":["0.110","0.101","0.0011","0.011"],"answer":3,"explanation":"0.375×2 = 0.75 → 0; 0.75×2 = 1.5 → 1; 0.5×2 = 1.0 → 1. Reading the integer parts in order gives 0.011 (= 1/4 + 1/8).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-130","question":"What is the result of the binary subtraction 11010 − 1101?","options":["1101","1011","1111","10011"],"answer":0,"explanation":"11010 = 26 and 1101 = 13; 26 − 13 = 13 = 1101 in binary.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-131","question":"The Binary Coded Decimal (8421 BCD) representation of the decimal number 59 is:","options":["0111 0011","0011 1011","0101 1010","0101 1001"],"answer":3,"explanation":"In BCD each decimal digit is coded separately in 4 bits: 5 = 0101, 9 = 1001. 0011 1011 is the pure binary of 59, a common trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-132","question":"A memory chip has 16 address lines and each location stores 1 byte. Its capacity is:","options":["32 KB","16 KB","64 KB","128 KB"],"answer":2,"explanation":"16 address lines can select 2¹⁶ = 65,536 locations; at 1 byte each, that is 65,536 bytes = 64 KB.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-133","question":"What is the minimum number of bits needed to give a unique binary code to 1000 different items?","options":["10","9","11","1000"],"answer":0,"explanation":"2⁹ = 512 is too small and 2¹⁰ = 1024 is enough, so 10 bits are needed.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-134","question":"The range of integers that can be stored in 8 bits using two's complement is:","options":["−127 to +127","−128 to +127","0 to 255","−256 to +255"],"answer":1,"explanation":"Two's complement in n bits covers −2ⁿ⁻¹ to 2ⁿ⁻¹ − 1, i.e. −128 to +127. −127 to +127 is the range in sign-magnitude or one's complement, which have two zeros.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-135","question":"By De Morgan's theorem, the complement of (A + B) is equal to:","options":["A′ + B′","A′ · B′","A · B","(A · B)′"],"answer":1,"explanation":"(A + B)′ = A′·B′, which is why a NOR gate equals an AND gate with inverted inputs. A′ + B′ is the complement of A·B, the other De Morgan law.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-136","question":"In which situation does an operating system suffer from 'thrashing'?","options":["The hard disk develops bad sectors","Two processes wait forever for resources held by each other","A low-priority process never gets the CPU","It spends more time swapping pages between memory and disk than executing processes"],"answer":3,"explanation":"Thrashing is excessive paging when processes do not have enough frames. Processes waiting on each other is deadlock; a process never getting the CPU is starvation.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-137","question":"In a class C network with subnet mask 255.255.255.0, how many usable host addresses are available?","options":["254","256","255","253"],"answer":0,"explanation":"8 host bits give 2⁸ = 256 addresses, minus the network address and the broadcast address = 254 usable hosts.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-138","question":"Which program combines several object files and library routines into a single executable file?","options":["Assembler","Loader","Linker","Interpreter"],"answer":2,"explanation":"The linker joins object modules into one executable. The loader then places the executable in memory to run it; the assembler converts assembly into object code.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-139","question":"TCP and UDP are protocols of which OSI layer, and which of them guarantees ordered, reliable delivery?","options":["Transport layer; TCP","Network layer; UDP","Transport layer; UDP","Session layer; TCP"],"answer":0,"explanation":"Both work at the Transport layer. TCP is connection-oriented with acknowledgements and ordering; UDP is connectionless and faster but unreliable.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-140","question":"The Excess-3 code of the decimal digit 4 is:","options":["1000","0100","0011","0111"],"answer":3,"explanation":"Excess-3 adds 3 to the digit before converting: 4 + 3 = 7 = 0111. 0100 is plain BCD of 4.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-141","question":"A processor negates the 8-bit value 00101100 using two's complement. Which bit pattern does it produce?","options":["11010011","11010100","11010101","10101100"],"answer":1,"explanation":"One's complement of 00101100 is 11010011; adding 1 gives 11010100. 11010011 is only the one's complement. Check: 00101100 + 11010100 = 1 00000000 (carry discarded).","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-142","question":"The binary number 1011 converted into Gray code is:","options":["1011","1101","1110","0110"],"answer":2,"explanation":"Gray code: keep the MSB (1), then XOR each pair of adjacent bits: 1⊕0 = 1, 0⊕1 = 1, 1⊕1 = 0. Result 1110.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-143","question":"(FF)₁₆ + (1)₁₆ − (100)₈ equals which decimal number?","options":["156","256","192","200"],"answer":2,"explanation":"FF + 1 = 100₁₆ = 256; 100₈ = 64. 256 − 64 = 192. Reading 100₈ as 100 decimal gives the trap 156.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-144","question":"What is the product of the binary numbers 1010 and 111, expressed in binary?","options":["1010111","1000110","1000100","111110"],"answer":1,"explanation":"1010 = 10 and 111 = 7; 10 × 7 = 70 = 64 + 4 + 2 = 1000110.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-145","question":"A network uses the subnet mask 255.255.255.192 (/26). How many usable host addresses does each subnet have?","options":["30","64","126","62"],"answer":3,"explanation":"/26 leaves 32 − 26 = 6 host bits: 2⁶ = 64 addresses minus network and broadcast = 62. 126 is for /25 and 30 for /27.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-146","question":"A 32-bit memory address is written in hexadecimal. How many hexadecimal digits does it take, and what is the largest address?","options":["8 digits; FFFFFFFF","4 digits; FFFF","8 digits; 99999999","16 digits; FFFFFFFFFFFFFFFF"],"answer":0,"explanation":"Each hex digit stands for 4 bits, so 32 bits need 8 hex digits; the largest is all ones = FFFFFFFF. 99999999 is not the maximum since hex digits go up to F.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-147","question":"Convert (345)₈ directly into base 16.","options":["159","D5","E5","E9"],"answer":2,"explanation":"345₈ = 011 100 101 in binary = 1110 0101 regrouped in fours = E5₁₆. Check: 3×64 + 4×8 + 5 = 229 = 14×16 + 5. 159 is just a wrong regrouping.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-148","question":"In which of the following is the Boolean identity stated INCORRECTLY?","options":["A + A′·B = A·B","A·(A + B) = A","A + A′ = 1","(A′)′ = A"],"answer":0,"explanation":"A + A′B simplifies to A + B, not AB. The others are correct: absorption A(A+B) = A, the complement law A + A′ = 1, and double complement (A′)′ = A.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-149","question":"A NAND gate has its two inputs tied together and fed with the signal X. The output is:","options":["X (it acts as a buffer)","X′ (it acts as a NOT gate)","Always 1","Always 0"],"answer":1,"explanation":"(X·X)′ = X′, so a NAND with joined inputs is an inverter — the first step in showing NAND is universal. It is always 1 only when at least one input is 0.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-150","question":"How many of these statements about computer memory are correct? I. SRAM is used for cache and does not need refreshing. II. EEPROM can be erased electrically, byte by byte. III. Flash memory is a type of EEPROM. IV. Registers are slower than cache memory.","options":["Only one","Only two","All four","Only three"],"answer":3,"explanation":"I, II and III are correct. IV is wrong — registers sit inside the CPU and are the fastest memory of all, faster than cache.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-151","question":"A sound file is recorded at 44,100 samples per second, 16 bits per sample, in stereo (2 channels). Ignoring compression, how many bytes does one second of audio take?","options":["7,05,600 bytes","88,200 bytes","14,11,200 bytes","1,76,400 bytes"],"answer":3,"explanation":"44,100 × 16 × 2 = 14,11,200 bits per second; ÷ 8 = 1,76,400 bytes. 14,11,200 is the bit figure, a trap for forgetting to divide by 8; 88,200 forgets the second channel.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-152","question":"Which of these is the correct order of the OSI layers from the bottom (layer 1) up to layer 4?","options":["Data Link, Physical, Transport, Network","Physical, Network, Data Link, Transport","Physical, Data Link, Network, Transport","Physical, Data Link, Transport, Network"],"answer":2,"explanation":"Layer 1 Physical, 2 Data Link, 3 Network, 4 Transport, then Session, Presentation and Application.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-153","question":"How many of these statements about IPv4 addressing are correct? I. A class A address has a first octet from 1 to 126. II. 172.16.5.4 is a private address. III. 192.168.10.0/24 has 256 usable host addresses. IV. 255.255.255.255 is a limited broadcast address.","options":["Only three","All four","Only two","Only one"],"answer":0,"explanation":"I, II and IV are correct (127 is reserved for loopback; 172.16–31.x.x is a private range). III is wrong: a /24 has 256 addresses but only 254 usable hosts.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-154","question":"The decimal number 45 is stored as an 8-bit unsigned binary number and then shifted left by 2 bits (zeros entering from the right, no overflow). The new decimal value is:","options":["90","180","47","11"],"answer":1,"explanation":"45 = 00101101; shifting left by 2 gives 10110100 = 128 + 32 + 16 + 4 = 180. Each left shift doubles the value, so 45 × 4 = 180. 11 would come from a right shift by 2.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-155","question":"Convert the hexadecimal number (2F7)₁₆ directly into octal.","options":["(1367)₈","(1357)₈","(1377)₈","(2367)₈"],"answer":0,"explanation":"2F7 = 0010 1111 0111; regrouping in threes from the right gives 001 011 110 111 = 1 3 6 7, so (1367)₈ (= 759 in decimal).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-156","question":"A cache has an access time of 10 ns and main memory 100 ns. The cache is checked first and, on a miss, the word is then read from main memory, so a miss costs 10 + 100 ns. With a hit ratio of 90%, what is the average memory access time?","options":["19 ns","20 ns","91 ns","55 ns"],"answer":1,"explanation":"Average = 0.9 × 10 + 0.1 × (10 + 100) = 9 + 11 = 20 ns. 19 ns comes from wrongly charging a miss only 100 ns, as if both memories were searched in parallel.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-157","question":"In the fetch phase of an instruction cycle, which register-to-register transfer happens first?","options":["The memory data register (MDR) is copied into the program counter (PC)","The instruction register (IR) is copied into the MDR","The program counter (PC) is copied into the memory address register (MAR)","The MAR is copied into the program counter (PC)"],"answer":2,"explanation":"The PC holds the address of the next instruction, so it is sent to the MAR to read memory; the fetched word arrives in the MDR and then moves to the IR.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-158","question":"A processor has a 20-bit address bus, and its memory is word-addressable with 16-bit (2-byte) words. What is the maximum memory it can address?","options":["1 MB","512 KB","16 MB","2 MB"],"answer":3,"explanation":"20 address lines select 2²⁰ words, and each word is 2 bytes, so 2²⁰ × 2 B = 2 MB. Answering 1 MB wrongly assumes each address holds one byte.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-159","question":"A system uses 32-bit virtual addresses and a page size of 4 KB. How many bits of the address form the page number and how many the offset within the page?","options":["20-bit page number, 12-bit offset","12-bit page number, 20-bit offset","22-bit page number, 10-bit offset","24-bit page number, 8-bit offset"],"answer":0,"explanation":"4 KB = 2¹² bytes, so 12 bits are needed for the offset; the remaining 32 − 12 = 20 bits give the page number (2²⁰ pages).","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-160","question":"Which of the following is NOT one of the four conditions that must all hold for a deadlock to occur?","options":["Mutual exclusion","Hold and wait","Circular wait","Pre-emption of resources"],"answer":3,"explanation":"The necessary conditions are mutual exclusion, hold and wait, NO pre-emption and circular wait. If resources can be pre-empted, deadlock can be broken, so pre-emption is not a condition for it.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-161","question":"Three processes arrive at time 0 in the order P1 (burst 10 ms), P2 (burst 4 ms) and P3 (burst 2 ms). By how much does the average waiting time under non-pre-emptive SJF fall compared with FCFS?","options":["8 ms","5.33 ms","2.67 ms","16 ms"],"answer":1,"explanation":"FCFS waits are 0, 10, 14 (average 8 ms); SJF runs P3, P2, P1 with waits 0, 2, 6 (average 2.67 ms). The fall is 8 − 2.67 = 5.33 ms; 16 ms is the fall in TOTAL waiting time, not the average.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-162","question":"In a STUDENT table, both RollNo and Email can uniquely identify every row. The designer chooses RollNo as the primary key. What is Email now called?","options":["A foreign key","A composite key","An alternate key","A surrogate key"],"answer":2,"explanation":"Every minimal unique identifier is a candidate key; the candidate keys not chosen as the primary key are alternate keys. A surrogate key is an artificial system-generated id, which Email is not.","difficulty":"moderate","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-163","question":"A relation is in 1NF and its primary key consists of a single attribute. Which normal form is it then guaranteed to satisfy?","options":["2NF","3NF","BCNF","None beyond 1NF"],"answer":0,"explanation":"2NF forbids partial dependency on part of a composite key; with a single-attribute key there is no 'part', so the relation is automatically in 2NF. It can still have transitive dependencies, so 3NF is not guaranteed.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-164","question":"A funds-transfer transaction commits successfully, and a second later the database server loses power. When it restarts, the transfer is still recorded. Which ACID property ensured this?","options":["Atomicity","Durability","Consistency","Isolation"],"answer":1,"explanation":"Durability guarantees that once a transaction commits, its changes survive later failures. Atomicity is about all-or-nothing execution before commit, not survival after it.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-165","question":"Which network device is matched with the WRONG OSI layer at which it mainly operates?","options":["Hub — Physical layer","Bridge — Data Link layer","Router — Network layer","Repeater — Network layer"],"answer":3,"explanation":"A repeater only regenerates the electrical signal, so it works at the Physical layer (layer 1), not the Network layer. The other three pairs are correct.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-166","question":"An IPv6 address is written as colon-separated groups of hexadecimal digits. In full (uncompressed) form, how many groups are there and how many bits does each group carry?","options":["16 groups of 8 bits","4 groups of 32 bits","8 groups of 16 bits","6 groups of 16 bits"],"answer":2,"explanation":"IPv6 is 128 bits, written as 8 groups of 4 hex digits; 4 hex digits = 16 bits, and 8 × 16 = 128. Six groups is the pattern of a 48-bit MAC address, not IPv6.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-167","question":"In a 48-bit MAC address, what do the first 24 bits (the Organisationally Unique Identifier) identify?","options":["The network to which the device is connected","The manufacturer of the network interface","The subnet mask of the device","The country where the device was registered"],"answer":1,"explanation":"The OUI is assigned to the manufacturer (vendor); the last 24 bits are the serial number given by that vendor. MAC addresses carry no network or subnet information; that is the job of IP addressing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-168","question":"The 8-bit pattern 11110110 stores a signed integer in two's complement form. What is its value?","options":["−118","246","−10","−9"],"answer":2,"explanation":"The MSB is 1, so it is negative; inverting and adding 1 gives 00001010 = 10, so the value is −10. −118 is the sign-magnitude reading, 246 the unsigned reading and −9 the one's-complement reading.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-169","question":"The Gray code 1101 is converted back into ordinary binary. What is the result?","options":["1011","1110","1101","1001"],"answer":3,"explanation":"Keep the first bit (1), then each binary bit = previous binary bit XOR current Gray bit: 1, 1⊕1 = 0, 0⊕0 = 0, 0⊕1 = 1, giving 1001. 1011 is what you get by converting binary to Gray instead.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-170","question":"What is (7A)₁₆ + (2C)₁₆, written in hexadecimal?","options":["A6","96","166","B6"],"answer":0,"explanation":"A + C = 10 + 12 = 22 = 16 + 6, so write 6 and carry 1; 7 + 2 + 1 = 10 = A, giving A6. 96 forgets the carry, and 166 is the decimal value of A6, not a hex result.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-171","question":"How many of these gates are 'universal', i.e. able to build every other logic function on their own: NAND, NOR, XOR, AND?","options":["One","Three","Two","Four"],"answer":2,"explanation":"Only NAND and NOR are universal. AND alone cannot make NOT, and XOR alone cannot make AND, so they are not universal.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-172","question":"Which type of ROM is erased by exposing the chip to ultraviolet light through a small quartz window on its package?","options":["EEPROM","PROM","Mask ROM","EPROM"],"answer":3,"explanation":"EPROM is erased with UV light and then reprogrammed. EEPROM (and flash) is erased electrically, while PROM is one-time programmable and mask ROM is fixed at manufacture.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-173","question":"Assertion (A): Dynamic RAM must be refreshed thousands of times every second. Reason (R): DRAM stores each bit as charge in a tiny capacitor, and the charge leaks away.","options":["A is true but R is false","Both A and R are true, but R is not the correct explanation of A","A is false but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"DRAM cells are capacitors whose charge leaks within milliseconds, which is exactly why they must be refreshed. SRAM uses flip-flops and needs no refresh.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-174","question":"Which sequence correctly describes what happens when a PC is switched on?","options":["Power-on self-test (POST) → boot loader runs → operating system kernel loads → user login","Boot loader runs → POST → kernel loads → user login","Kernel loads → POST → boot loader runs → user login","POST → kernel loads → boot loader runs → user login"],"answer":0,"explanation":"Firmware (BIOS/UEFI) first runs the POST, then finds and runs the boot loader, which loads the OS kernel; only then is the user offered a login. The kernel cannot load before the boot loader that loads it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-175","question":"In which order does a compiler normally carry out these phases on a source program?","options":["Syntax analysis → lexical analysis → semantic analysis → code generation","Lexical analysis → semantic analysis → syntax analysis → code generation","Lexical analysis → syntax analysis → semantic analysis → code generation","Lexical analysis → syntax analysis → code generation → semantic analysis"],"answer":2,"explanation":"The source is first split into tokens (lexical), then tokens are arranged into a parse tree (syntax), then checked for meaning such as types (semantic), and only then is code generated.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-176","question":"A 5-stage instruction pipeline takes one clock cycle per stage and never stalls. How many clock cycles does it need to complete 100 instructions?","options":["500","104","105","100"],"answer":1,"explanation":"The first instruction needs 5 cycles to fill the pipeline, and each of the remaining 99 finishes one cycle later: 5 + 99 = 104. 500 is the count without pipelining.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-177","question":"How many of these statements about RISC and CISC processors are correct? I. RISC designs usually use fixed-length instructions. II. CISC designs offer more addressing modes. III. RISC follows a load/store design, where only load and store instructions access memory. IV. Every CISC instruction completes in one clock cycle.","options":["One","Two","Four","Three"],"answer":3,"explanation":"I, II and III are correct. IV is false: complex CISC instructions often take many cycles; single-cycle execution is a RISC goal.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-178","question":"The Boolean expression A'B + AB' + AB (where ' means NOT) simplifies to which single operation on A and B?","options":["A OR B","A XOR B","A AND B","NOT A OR NOT B"],"answer":0,"explanation":"AB' + AB = A(B' + B) = A, so the expression becomes A + A'B = A + B, i.e. A OR B. XOR would be only the first two terms; the extra AB term adds the case A = B = 1.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-179","question":"A hard disk spins at 7200 rpm and has an average seek time of 8 ms. Ignoring transfer and controller time, what is its average access time?","options":["16.33 ms","8.33 ms","12.17 ms","4.17 ms"],"answer":2,"explanation":"One rotation takes 60,000 ÷ 7200 = 8.33 ms, and on average the head waits half a rotation (4.17 ms). Access time = 8 + 4.17 ≈ 12.17 ms; 16.33 ms wrongly adds a full rotation.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-180","question":"How many of these statements are correct? I. A solid-state drive has no moving read/write head. II. Flash memory cells can be rewritten only a limited number of times. III. SSDs should be defragmented regularly to keep them fast. IV. Random reads are much faster on an SSD than on a hard disk.","options":["Two","Three","One","Four"],"answer":1,"explanation":"I, II and IV are true. III is false: an SSD has no seek time, so fragmentation hardly slows it, and needless defragmentation only wears out its limited write cycles.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-181","question":"In a virtual memory system, a 'page fault' occurs when a program refers to a page that:","options":["is not present in the cache memory","has no entry in the translation lookaside buffer (TLB)","belongs to the address space of another process","is not currently loaded in main memory"],"answer":3,"explanation":"A page fault means the page is on disk, not in RAM, so the OS must load it. A TLB miss only means the translation must be read from the page table; the page may well be in RAM.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-182","question":"A program reads the elements of a large array one after another: a[0], a[1], a[2] and so on. Which property does the cache exploit to speed this up?","options":["Spatial locality","Temporal locality","Thrashing","Write-back"],"answer":0,"explanation":"Neighbouring addresses are used soon after one another, so loading a whole cache block at once helps: that is spatial locality. Temporal locality is reuse of the SAME address, such as a loop counter.","difficulty":"moderate","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-183","question":"Under a write-back cache policy, when is a modified cache block written to main memory?","options":["Immediately, on every write to the block","Only when the block is about to be replaced, as shown by its dirty bit","Only when the program terminates","Never; main memory is updated by the DMA controller"],"answer":1,"explanation":"Write-back marks a changed block 'dirty' and copies it to memory only when it is evicted. Writing on every update is the write-through policy.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-184","question":"How many of these statements about the system bus are correct? I. The address bus carries addresses from the CPU to memory, so it is unidirectional. II. The data bus is bidirectional. III. The width of the data bus decides how much memory can be addressed. IV. Read and write signals travel on the control bus.","options":["Three","Two","One","Four"],"answer":0,"explanation":"I, II and IV are correct. III is wrong: the ADDRESS bus width sets the addressable memory (n lines give 2ⁿ locations); the data bus width sets how many bits move at a time.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-185","question":"Convert (563)₈ directly into hexadecimal.","options":["(371)₁₆","(1B3)₁₆","(163)₁₆","(173)₁₆"],"answer":3,"explanation":"563 = 101 110 011 in binary; regroup in fours from the right: 1 0111 0011 = 1 7 3, so (173)₁₆. 371 is the decimal value, not hex.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-186","question":"The decimal number 156 is stored once in pure binary and once in 8421 BCD. How many more bits does the BCD form need?","options":["None","Two","Four","Three"],"answer":2,"explanation":"156 in binary is 10011100 (8 bits). BCD codes each digit in 4 bits: 0001 0101 0110 (12 bits). The difference is 4 bits.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-187","question":"What is the largest unsigned number that 12 bits can hold, written in octal?","options":["(7777)₈","(4095)₈","(777)₈","(3777)₈"],"answer":0,"explanation":"The largest 12-bit value is 2¹² − 1 = 4095 = 111 111 111 111, and each group of three 1s is 7, giving (7777)₈. '4095' is the decimal value and is not even a valid octal numeral.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-188","question":"Which of these IPv4 addresses is a PRIVATE address that cannot be routed on the public internet?","options":["172.32.1.1","192.169.1.1","172.20.5.4","11.0.0.1"],"answer":2,"explanation":"The private ranges are 10.0.0.0/8, 172.16.0.0–172.31.255.255 and 192.168.0.0/16. 172.20.5.4 lies inside 172.16–172.31; 172.32 is just outside it, and 192.169 and 11 are public.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-189","question":"Six computers are joined in a full mesh topology. How many cables are needed, and how many ports must each computer have?","options":["30 cables, 5 ports each","15 cables, 6 ports each","30 cables, 6 ports each","15 cables, 5 ports each"],"answer":3,"explanation":"Each pair needs one link: 6 × 5 ÷ 2 = 15 cables, and each computer connects to the other 5, so it needs 5 ports. 30 counts every cable twice.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-190","question":"A bank must link two buildings that sit next to a power substation causing heavy electrical noise. Which cable is the best choice?","options":["Unshielded twisted pair","Coaxial cable","Optical fibre","Shielded twisted pair"],"answer":2,"explanation":"Optical fibre carries light, not electrical signals, so electromagnetic interference cannot affect it. Shielding on copper cables only reduces interference; it does not remove it.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-191","question":"The 'ping' command checks whether a host can be reached. Which protocol do its echo request and echo reply messages use?","options":["ICMP","TCP","UDP","ARP"],"answer":0,"explanation":"Ping sends ICMP Echo Request messages and waits for Echo Replies. ICMP is a network-layer control protocol and uses no TCP or UDP port; ARP only maps IP to MAC on a LAN.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-192","question":"A walkie-talkie, a television broadcast and an ordinary telephone call are examples of which transmission modes, respectively?","options":["Simplex, half-duplex, full-duplex","Full-duplex, simplex, half-duplex","Half-duplex, simplex, full-duplex","Half-duplex, full-duplex, simplex"],"answer":2,"explanation":"Walkie-talkie users talk in turn (half-duplex), TV flows only one way (simplex), and both phone callers can speak at once (full-duplex).","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-193","question":"Ten users must each be able to talk privately with every other user. How many keys are needed in total with symmetric-key encryption, and how many with public-key encryption?","options":["20 and 45","45 and 20","90 and 20","45 and 10"],"answer":1,"explanation":"Symmetric: one shared secret key per pair, 10 × 9 ÷ 2 = 45. Public-key: each user needs only one key pair, so 10 × 2 = 20 keys. 10 counts only the public keys.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-194","question":"A piece of malware copies itself from computer to computer across a network on its own, without attaching to any file or needing a user to run a program. It is a:","options":["Virus","Trojan horse","Worm","Logic bomb"],"answer":2,"explanation":"A worm is self-replicating and standalone. A virus needs a host file and some user action to spread, and a Trojan disguises itself as useful software but does not replicate.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-195","question":"A bank publishes a value computed from a software installer so that customers can confirm the download has not been altered. The file itself stays readable by anyone. Which technique is this?","options":["Symmetric encryption","Steganography","Public-key encryption","Cryptographic hashing"],"answer":3,"explanation":"A hash (such as SHA-256) is a one-way fingerprint: any change to the file changes it, so it checks integrity. Encryption would hide the content, which is not the goal here.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-196","question":"On what basis does a simple packet-filtering firewall allow or block traffic?","options":["Source and destination IP addresses, ports and protocol in each packet header","The full content of e-mail attachments","The identity of the logged-in user on each PC","The reputation of the website's owner"],"answer":0,"explanation":"Packet filters look only at header fields such as IP addresses, port numbers and protocol. Inspecting content or user identity needs application-level or next-generation firewalls.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-197","question":"Which SQL command removes all the rows of a table AND the table's definition, so the table no longer exists?","options":["TRUNCATE TABLE","DELETE FROM","DROP TABLE","ALTER TABLE"],"answer":2,"explanation":"DROP removes the data and the structure. TRUNCATE and DELETE without WHERE empty the table but leave its definition in place.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-198","question":"An ORDERS table has CustomerID as a foreign key referring to CUSTOMER. A clerk tries to insert an order with CustomerID 9999, which does not exist in CUSTOMER. Which constraint is violated?","options":["Entity integrity","Domain integrity","Uniqueness of the primary key","Referential integrity"],"answer":3,"explanation":"Referential integrity requires every foreign-key value to match an existing primary key (or be NULL). Entity integrity concerns NULLs in the primary key of the same table.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-199","question":"Which SQL command is placed in the WRONG category?","options":["CREATE — Data Definition Language","GRANT — Data Control Language","UPDATE — Data Definition Language","SELECT — Data Query/Manipulation Language"],"answer":2,"explanation":"UPDATE changes the data inside a table, so it is DML. DDL commands (CREATE, ALTER, DROP, TRUNCATE) change the structure.","difficulty":"moderate","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-200","question":"Which of the following is NOT shared by the threads of one process?","options":["The program code","Global data","Open files","The stack"],"answer":3,"explanation":"Threads share their process's code, global data and open files, but each thread has its own stack and registers so it can run its own sequence of calls.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-201","question":"Print jobs from many users are first stored on disk and sent to a slow printer one by one, so the CPU can carry on with other work. This technique is called:","options":["Spooling","Paging","Thrashing","Swapping"],"answer":0,"explanation":"Spooling (Simultaneous Peripheral Operations On-Line) queues output for a slow device on disk. Paging and swapping move memory pages or processes, and thrashing is excessive paging.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-202","question":"Which sequence correctly describes how a TCP connection is set up by the three-way handshake?","options":["Server sends SYN first, client replies with SYN-ACK, server finishes with ACK","Client sends SYN, server replies with SYN-ACK, client finishes with ACK","Client sends SYN, server replies with FIN, client finishes with ACK","Client sends SYN and ACK together, server replies with SYN, client sends nothing more"],"answer":1,"explanation":"The side opening the connection (client) sends SYN, the server answers SYN-ACK (its own SYN plus an acknowledgement), and the client confirms with ACK. FIN is used to CLOSE a connection.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-203","question":"How does the Harvard architecture differ from the von Neumann architecture?","options":["It has no main memory, only registers","It keeps instructions and data in separate memories with separate buses","It stores programs on magnetic tape instead of RAM","It uses decimal rather than binary arithmetic"],"answer":1,"explanation":"Von Neumann machines share one memory and bus for code and data (causing the 'von Neumann bottleneck'); Harvard designs give instructions and data separate memories and paths so both can be fetched at once.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-204","question":"A processor runs at 2 GHz. An instruction that needs 4 clock cycles takes how long to execute?","options":["8 ns","0.5 ns","2 ns","0.125 ns"],"answer":2,"explanation":"At 2 GHz one cycle lasts 1 ÷ (2 × 10⁹) s = 0.5 ns, so 4 cycles take 2 ns. 8 ns wrongly multiplies the frequency by the cycles.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-205","question":"A 2 GHz processor needs on average 2.5 clock cycles per instruction (CPI). What is its speed in MIPS (million instructions per second)?","options":["5000 MIPS","800 MIPS","500 MIPS","1250 MIPS"],"answer":1,"explanation":"MIPS = clock rate ÷ (CPI × 10⁶) = 2000 MHz ÷ 2.5 = 800. Multiplying by the CPI instead of dividing gives the trap answer 5000.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-206","question":"A file system divides a 2 GB partition into blocks of 4 KB each (1 KB = 1024 bytes, 1 GB = 1024 MB). How many blocks are there?","options":["500,000","512,000","262,144","524,288"],"answer":3,"explanation":"2 GB = 2³¹ bytes and 4 KB = 2¹² bytes, so there are 2³¹ ÷ 2¹² = 2¹⁹ = 524,288 blocks. 500,000 comes from using powers of 10, which the question rules out.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-207","question":"An uncompressed image is 1920 × 1080 pixels with 24-bit colour. Taking 1 MB = 1024 × 1024 bytes, about how much storage does it need?","options":["About 47.5 MB","About 5.9 MB","About 2.0 MB","About 0.74 MB"],"answer":1,"explanation":"24 bits = 3 bytes per pixel: 1920 × 1080 × 3 = 6,220,800 bytes ≈ 5.93 MB. 47.5 MB forgets to convert bits to bytes, and 2.0 MB treats each pixel as 1 byte.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-208","question":"A branch needs a printer that can print the original and carbon copies of a multi-part form in a single pass. Which printer suits this?","options":["Laser printer","Dot-matrix printer","Inkjet printer","Thermal printer"],"answer":1,"explanation":"Only an impact printer such as dot-matrix strikes the paper hard enough to mark the copies underneath. Laser, inkjet and thermal printers are non-impact.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-209","question":"Match each reader with its typical use: 1. MICR 2. OMR 3. OCR 4. Barcode reader; a. converting a scanned printed page into editable text b. reading the code line at the bottom of a cheque c. checking shaded bubbles on an exam answer sheet d. reading a product's price tag at a billing counter","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d"],"answer":1,"explanation":"MICR reads magnetic-ink characters on cheques, OMR detects pencil marks in fixed positions, OCR recognises printed characters, and barcode readers read product codes.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-210","question":"Which port carries both high-definition digital video and multichannel audio over a single cable?","options":["VGA","PS/2","HDMI","DVI"],"answer":2,"explanation":"HDMI carries digital video and audio together. VGA is analogue video only, DVI is designed for video, and PS/2 connected keyboards and mice.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-211","question":"How many of these statements about CPU cache levels are correct? I. L1 cache is the smallest and fastest. II. In multi-core processors, L3 cache is usually shared by all the cores. III. L2 cache is larger than L1 but slower. IV. L3 cache is faster than L1 because it is bigger.","options":["Two","Three","Four","One"],"answer":1,"explanation":"I, II and III are correct. IV is wrong: bigger caches are slower, so speed falls from L1 to L2 to L3.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-212","question":"A disk controller copies a large block of data straight into RAM and interrupts the CPU only once, when the whole transfer is over. This technique is:","options":["Programmed I/O with polling","Interrupt-driven I/O, one interrupt per byte","Spooling","Direct Memory Access (DMA)"],"answer":3,"explanation":"With DMA the controller moves the data itself and signals the CPU only at the end, leaving the CPU free. In programmed and interrupt-driven I/O, the CPU handles every word.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-213","question":"A server with four CPUs runs four different processes truly at the same instant. This is best described as:","options":["Multiprogramming","Multiprocessing","Time-sharing on a single processor","Batch processing"],"answer":1,"explanation":"Multiprocessing uses more than one processor, so several processes run in parallel. Multiprogramming and time-sharing on one CPU only interleave processes; they never run at the same instant.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-214","question":"A user program needs to read a file from disk, which only the operating system may do. How does it get the OS to do this?","options":["By making a system call, which switches the CPU into kernel mode","By writing directly to the disk controller's registers","By calling the BIOS from user mode","By raising its own process priority"],"answer":0,"explanation":"Protected operations run in kernel mode; a user program requests them through a system call (trap). Direct hardware access from user mode is blocked by the OS.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-215","question":"Which pairing of memory-management scheme and the kind of fragmentation it suffers from is correct?","options":["Paging — external; segmentation — internal","Paging — none; segmentation — none","Paging — internal; segmentation — external","Paging — internal; segmentation — internal"],"answer":2,"explanation":"Paging uses fixed-size frames, so space is wasted inside the last page (internal). Segments vary in size, leaving scattered free holes between them (external).","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-216","question":"A process has 3 page frames, all empty at first, and refers to pages in the order 5, 0, 3, 5, 1, 0, 5, 2, 0, 1, 3. How many page faults occur under FIFO and under LRU replacement?","options":["FIFO 8, LRU 9","FIFO 9, LRU 9","FIFO 9, LRU 8","FIFO 6, LRU 8"],"answer":2,"explanation":"FIFO faults on 5, 0, 3, 1, 5, 2, 0, 1, 3 = 9. LRU keeps 5 and 0 longer because they were just used and faults on 5, 0, 3, 1, 0, 2, 1, 3 = 8. Six is the count for the optimal policy.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-217","question":"Arrange these networks from the smallest to the largest geographical coverage.","options":["LAN < PAN < MAN < WAN","PAN < LAN < WAN < MAN","PAN < MAN < LAN < WAN","PAN < LAN < MAN < WAN"],"answer":3,"explanation":"A PAN covers a person's surroundings (e.g. Bluetooth), a LAN a building, a MAN a city, and a WAN countries or the globe.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-218","question":"Under classful addressing, what is the default subnet mask of the host 150.10.5.7?","options":["255.0.0.0","255.255.0.0","255.255.255.0","255.255.255.255"],"answer":1,"explanation":"A first octet of 128–191 marks a class B address, whose default mask is 255.255.0.0. Class A (1–126) uses 255.0.0.0 and class C (192–223) uses 255.255.255.0.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-219","question":"A host has the address 192.168.10.77/26. What are the network address and the broadcast address of its subnet?","options":["192.168.10.0 and 192.168.10.255","192.168.10.77 and 192.168.10.127","192.168.10.64 and 192.168.10.128","192.168.10.64 and 192.168.10.127"],"answer":3,"explanation":"/26 makes blocks of 64 addresses: 0–63, 64–127, 128–191, 192–255. 77 falls in 64–127, so the network is .64 and the broadcast is .127. The .0/.255 pair ignores the subnet mask.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-220","question":"Which protocol transfers files securely by running over an SSH connection?","options":["SFTP","FTP","TFTP","SMTP"],"answer":0,"explanation":"SFTP (SSH File Transfer Protocol) uses SSH, by default on port 22, for encrypted transfer. FTP and TFTP send data in plain text, and SMTP sends e-mail.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-221","question":"A bank clerk logs in with a valid password but finds he can only view loan files, not approve them. The rule that limits what he may do after logging in is called:","options":["Authentication","Authorisation","Non-repudiation","Encryption"],"answer":1,"explanation":"Authentication proves WHO the user is (the password); authorisation decides WHAT that user may access or do. Non-repudiation stops someone denying an action they took.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-222","question":"An outsider without an access card walks into a bank's server room by closely following an employee through the secured door. This social-engineering trick is called:","options":["Shoulder surfing","Tailgating","Dumpster diving","Vishing"],"answer":1,"explanation":"Tailgating (piggybacking) means slipping into a restricted area behind someone authorised. Shoulder surfing is watching someone type, dumpster diving is searching discarded material, and vishing is voice phishing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-223","question":"The word BANK is encrypted with a Caesar cipher that shifts each letter 3 places forward in the alphabet. What is the ciphertext?","options":["YXKH","EDQN","EDNQ","CBOL"],"answer":1,"explanation":"B→E, A→D, N→Q, K→N gives EDQN. YXKH shifts backwards, and CBOL shifts by only 1.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-224","question":"In SQL, which clause filters the groups produced by GROUP BY, for example to keep only branches whose total deposits exceed ₹1 crore?","options":["WHERE","ORDER BY","HAVING","DISTINCT"],"answer":2,"explanation":"WHERE filters individual rows BEFORE grouping and cannot use aggregates such as SUM(); HAVING filters the groups AFTER aggregation.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-225","question":"A table CUSTOMER has 6 rows; the Phone column is NULL in 2 of them. What do COUNT(*) and COUNT(Phone) return?","options":["6 and 6","4 and 4","6 and 4","4 and 6"],"answer":2,"explanation":"COUNT(*) counts every row, including those with NULLs, so it gives 6; COUNT(column) ignores NULL values, so COUNT(Phone) gives 4.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-226","question":"A bank allows joint accounts: one customer may hold several accounts, and one account may belong to several customers. What is the cardinality of the CUSTOMER–ACCOUNT relationship?","options":["One-to-one","One-to-many","Many-to-one","Many-to-many"],"answer":3,"explanation":"Both sides can have more than one partner, so it is many-to-many; in a relational design it needs a separate linking table such as DEPOSITOR(CustomerID, AccountNo).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-227","question":"In an ER model, the entity DEPENDENT (an employee's family member) cannot be uniquely identified without the EMPLOYEE it belongs to. What is DEPENDENT, and how is it drawn?","options":["A weak entity, drawn as a double rectangle","A strong entity, drawn as a double rectangle","A derived attribute, drawn as a dashed ellipse","A weak entity, drawn as a dashed ellipse"],"answer":0,"explanation":"An entity with no key of its own, identified through an owner entity, is a weak entity and is shown with a double rectangle (its identifying relationship as a double diamond). A dashed ellipse marks a derived attribute.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-228","question":"A database administrator moves a table to a faster disk and adds a new index. Neither the logical schema nor any application program has to change. This illustrates:","options":["Physical data independence","Logical data independence","Data redundancy","Referential integrity"],"answer":0,"explanation":"Changing how data is stored without affecting the logical (conceptual) schema is physical data independence. Logical data independence is changing the logical schema without affecting user views, which is harder to achieve.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-229","question":"Assertion (A): Creating an index on a column makes searches on that column faster. Reason (R): Every INSERT or UPDATE on the table must also update the index.","options":["A is true but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"Both statements are true, but R describes the COST of an index (slower writes), not why searches get faster. Searches speed up because the index is a sorted structure (such as a B-tree) that avoids scanning the whole table.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-230","question":"How many of these statements are correct? I. A table can have only one primary key. II. A primary key column can never hold NULL. III. A table can have several UNIQUE constraints. IV. A primary key may consist of more than one column.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four are correct: a table has one primary key, which is NOT NULL and unique, but it may be composite (several columns), and any number of other columns can carry UNIQUE constraints.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-231","question":"Two ATMs read a joint account's balance of ₹10,000 at the same moment. Each pays out ₹3,000 and writes back its own result. With no locking, what is this problem called and what balance is finally stored?","options":["A race condition (lost update); ₹7,000","A deadlock; ₹4,000","A race condition (lost update); ₹4,000","Starvation; ₹7,000"],"answer":0,"explanation":"Both ATMs compute 10,000 − 3,000 = 7,000, and the second write overwrites the first, so one withdrawal is lost and ₹7,000 is stored instead of ₹4,000. This lost update caused by uncontrolled concurrent access is a race condition.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-232","question":"A pen drive shows 20 GB free, yet copying a single 6 GB video file to it fails. Which is the most likely reason?","options":["The drive is formatted as FAT32, which cannot store a single file larger than 4 GB","The drive is formatted as NTFS, which cannot store a single file larger than 4 GB","USB ports cannot transfer files larger than 4 GB","Video files cannot be copied to removable media"],"answer":0,"explanation":"FAT32 limits each file to just under 4 GB, whatever the free space; reformatting to NTFS or exFAT removes the limit. NTFS supports very large files.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-233","question":"The controller that fires a car's airbag must respond within a few milliseconds every single time. What kind of operating system does it need?","options":["A batch operating system","A time-sharing operating system","A hard real-time operating system","A network operating system"],"answer":2,"explanation":"A hard real-time OS guarantees a response within a fixed deadline, where a late answer counts as a failure. Time-sharing systems aim for fair sharing, not guaranteed deadlines.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-234","question":"Which part of an operating system reads the commands a user types and passes them on to the kernel to be carried out?","options":["The BIOS","The compiler","The device driver","The shell"],"answer":3,"explanation":"The shell (command interpreter) is the interface between the user and the kernel. The kernel manages hardware and resources, but it does not read typed commands itself.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-235","question":"A program can be downloaded and used at no cost for as long as you like, but its source code is kept secret and you may not modify it. It is:","options":["Freeware","Open-source software","Shareware","Copyleft software"],"answer":0,"explanation":"Freeware is free of charge but closed. Open-source and copyleft software make the source available to modify, and shareware is free only for a trial period or with limited features.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-236","question":"Which system program copies an executable file from disk into main memory and prepares it to start running?","options":["Assembler","Linker","Loader","Compiler"],"answer":2,"explanation":"The loader places the program in memory (adjusting addresses if needed) and hands control to it. The linker runs earlier, joining object files into the executable.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-237","question":"Assertion (A): The decimal fraction 0.1 cannot be stored exactly in binary floating point. Reason (R): 1/10 has the factor 5 in its denominator, so its binary expansion repeats forever.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Only fractions whose denominator is a power of 2 terminate in binary. 0.1 = 1/(2 × 5) becomes 0.000110011… repeating, so it is rounded when stored; R gives exactly this reason.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-238","question":"What is (1010.11)₂ + (3.25)₁₀, expressed in binary?","options":["(1101.11)₂","(1110.11)₂","(1101.01)₂","(1110)₂"],"answer":3,"explanation":"(1010.11)₂ = 8 + 2 + 0.5 + 0.25 = 10.75, and 10.75 + 3.25 = 14 = (1110)₂. The fractional parts add up to exactly 1, so no fraction is left.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-239","question":"If (121)_b = (49)₁₀, what is the base b?","options":["6","7","8","5"],"answer":0,"explanation":"(121)_b = b² + 2b + 1 = (b + 1)² = 49, so b + 1 = 7 and b = 6. Check: 36 + 12 + 1 = 49. Base 7 would give 64.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-240","question":"A 16-bit register holds (FFFF)₁₆, read as a two's-complement signed integer. What value does it hold?","options":["65535","−32768","−1","−32767"],"answer":2,"explanation":"All 16 bits are 1; inverting gives 0 and adding 1 gives 1, so the value is −1. 65535 is the unsigned reading, and −32768 is the pattern 8000.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-241","question":"Two 8-bit two's-complement numbers, 01100100 (100) and 00110010 (50), are added. What does the 8-bit result hold?","options":["10010110, which reads as −106: an overflow has occurred","10010110, which reads as 150: no overflow","01111111: the result is held at the maximum, 127","00010110 with a carry out of 1, which reads as 22"],"answer":0,"explanation":"The sum 150 exceeds the 8-bit signed maximum of 127. The bits 10010110 are produced, which in two's complement mean 150 − 256 = −106; adding two positives and getting a negative is the sign of overflow.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-242","question":"In a half adder, which gates produce the Sum and the Carry outputs?","options":["Sum from AND, Carry from XOR","Sum from XOR, Carry from AND","Sum from OR, Carry from AND","Sum from XNOR, Carry from OR"],"answer":1,"explanation":"Adding two bits gives Sum = 1 when exactly one input is 1 (XOR) and Carry = 1 only when both are 1 (AND).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-243","question":"For how many of the 8 possible combinations of the inputs A, B and C does the circuit (A NAND B) NOR C output 1?","options":["7","3","5","1"],"answer":3,"explanation":"A NOR gate outputs 1 only when both its inputs are 0: A NAND B = 0 needs A = B = 1, and C must be 0. Only the combination A = 1, B = 1, C = 0 works.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-244","question":"Twenty-four PCs are connected one to a port on a 24-port switch with no VLANs configured. How many collision domains and how many broadcast domains does this network have?","options":["24 collision domains, 1 broadcast domain","1 collision domain, 1 broadcast domain","1 collision domain, 24 broadcast domains","24 collision domains, 24 broadcast domains"],"answer":0,"explanation":"Each switch port is its own collision domain, but a switch forwards broadcasts to every port, so there is one broadcast domain; only a router (or VLANs) splits broadcast domains. With a hub, there would be 1 collision domain.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-245","question":"Bank staff working from home need to reach the office network over the public internet, with all traffic encrypted as if they were inside the office. Which technology provides this?","options":["Network Address Translation (NAT)","A proxy server","A virtual private network (VPN)","A demilitarised zone (DMZ)"],"answer":2,"explanation":"A VPN builds an encrypted tunnel across the public internet into the private network. NAT only maps private to public addresses, and a DMZ is a separate zone for public-facing servers.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-246","question":"A bank rents virtual machines, storage and network capacity from a cloud provider, then installs and manages its own operating system and applications on them. Which cloud service model is this?","options":["Software as a Service (SaaS)","Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Function as a Service (FaaS)"],"answer":1,"explanation":"In IaaS the provider supplies raw computing infrastructure and the customer manages the OS upwards. In PaaS the provider also manages the OS and runtime, and in SaaS the whole application.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-247","question":"Match the IEEE standard with the technology: 1. IEEE 802.3 2. IEEE 802.11 3. IEEE 802.15; a. Wireless LAN (Wi-Fi) b. Wired Ethernet c. Wireless personal area network such as Bluetooth","options":["1-a, 2-b, 3-c","1-c, 2-a, 3-b","1-b, 2-c, 3-a","1-b, 2-a, 3-c"],"answer":3,"explanation":"802.3 is Ethernet, 802.11 is Wi-Fi and 802.15 covers wireless personal area networks, including Bluetooth (802.15.1).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-248","question":"A hypervisor installed directly on a server's hardware, with no host operating system beneath it, is called a:","options":["Type 1 (bare-metal) hypervisor","Type 2 (hosted) hypervisor","Container engine","Boot loader"],"answer":0,"explanation":"Type 1 hypervisors run straight on the hardware; Type 2 hypervisors run as an application on top of an ordinary host OS. Containers share the host kernel instead of virtualising hardware.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-249","question":"The processing speed of supercomputers is usually compared using which unit?","options":["MIPS","Clock speed in GHz","FLOPS","Revolutions per minute (rpm)"],"answer":2,"explanation":"Supercomputers do heavy scientific calculations, so they are rated in floating-point operations per second (FLOPS), e.g. petaFLOPS. MIPS counts general instructions, and GHz alone ignores how much work each cycle does.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-250","question":"Which pair consists ONLY of lossless compression formats, from which the original data can be rebuilt exactly?","options":["JPEG and MP3","PNG and JPEG","ZIP and MP3","ZIP and PNG"],"answer":3,"explanation":"ZIP archives and PNG images are lossless. JPEG and MP3 are lossy: they throw away detail the eye or ear is unlikely to notice, so the original cannot be restored exactly.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-251","question":"In the IEEE 754 single-precision (32-bit) floating-point format, how are the bits divided, and what is the exponent bias?","options":["1 sign, 8 exponent, 23 fraction bits; bias 128","1 sign, 11 exponent, 20 fraction bits; bias 1023","1 sign, 8 exponent, 23 fraction bits; bias 127","1 sign, 7 exponent, 24 fraction bits; bias 63"],"answer":2,"explanation":"Single precision is 1 + 8 + 23 = 32 bits with exponent bias 2⁷ − 1 = 127; 11 exponent bits and bias 1023 belong to the 64-bit double format.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-252","question":"In IEEE 754 single precision, the number 6.5 is stored as which 32-bit pattern, written in hexadecimal?","options":["40D00000","41500000","40E80000","40C00000"],"answer":0,"explanation":"6.5 = 110.1₂ = 1.101 × 2²; sign 0, exponent 2 + 127 = 10000001, fraction 101 then zeros (the leading 1 is hidden), giving 0100 0000 1101 0000 … = 40D00000. Keeping the hidden 1 gives 40E80000.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-253","question":"In 8-bit one's complement representation, how many bit patterns stand for zero, and what range of integers can be stored?","options":["One pattern; −128 to +127","Two patterns; −128 to +127","One pattern; −127 to +127","Two patterns; −127 to +127"],"answer":3,"explanation":"Both 00000000 (+0) and 11111111 (−0) mean zero in one's complement, so the range is only −127 to +127; a single zero with −128 to +127 is two's complement.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-254","question":"The 8-bit pattern 10000101 is read as a sign-magnitude, a one's complement and a two's complement number. Which list gives its values in that order?","options":["−5, −123, −122","−5, −122, −123","−122, −5, −123","−123, −122, −5"],"answer":1,"explanation":"Sign-magnitude: sign 1, magnitude 0000101 = 5, so −5. One's complement: invert to 01111010 = 122, so −122. Two's complement: −128 + 5 = −123.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-255","question":"A Hamming code must correct any single-bit error in a block of 12 data bits. What is the minimum number of check (parity) bits needed?","options":["4","5","6","3"],"answer":1,"explanation":"Check bits p must satisfy 2ᵖ ≥ m + p + 1. With m = 12, p = 4 gives 16 ≥ 17 (false) and p = 5 gives 32 ≥ 18, so 5 are needed; 4 suffice only up to 11 data bits.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-256","question":"A sender appends an even-parity bit to every 7-bit character. Which received 8-bit word shows that an error has occurred?","options":["10110100","11100111","00000000","01011011"],"answer":3,"explanation":"Under even parity every valid word has an even count of 1s. 01011011 has five 1s, so a bit has flipped; the others have four, six and zero 1s.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-257","question":"In ASCII the capital letter 'G' has the code 71 (decimal). What is the code of the small letter 'g', written in hexadecimal?","options":["67","47","77","57"],"answer":0,"explanation":"Small letters are 32 more than capitals, so 'g' = 71 + 32 = 103 = 6 × 16 + 7 = (67)₁₆. (47)₁₆ is the code of 'G' itself.","difficulty":"moderate","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-258","question":"In ASCII, 'M' is 77 and 'm' is 109, so changing one into the other flips exactly one bit. What is the place value of that bit?","options":["16","64","32","128"],"answer":2,"explanation":"109 − 77 = 32 = 2⁵, so toggling bit 5 switches the case of any ASCII letter; 7-bit ASCII never uses the 128 bit at all.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-259","question":"A text file is saved in UTF-8. How many bytes does the English letter 'A' take, and how many does a Devanagari letter such as 'क' take?","options":["1 byte and 2 bytes","2 bytes and 2 bytes","1 byte and 4 bytes","1 byte and 3 bytes"],"answer":3,"explanation":"UTF-8 keeps ASCII in one byte; code points U+0800 to U+FFFF, which include the Devanagari block (U+0900–U+097F), take three bytes. Two bytes reach only U+07FF.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-260","question":"In which number base is the statement 3 × 4 = 13 true?","options":["Base 8","Base 9","Base 7","Base 12"],"answer":1,"explanation":"3 × 4 = 12 in decimal, and 13 in base b means b + 3. So b + 3 = 12 gives b = 9.","difficulty":"moderate","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-261","question":"Three of these numbers are equal. Which one has a different value?","options":["(25)₁₆","(100110)₂","(46)₈","(38)₁₀"],"answer":0,"explanation":"(100110)₂ = 32 + 4 + 2 = 38 and (46)₈ = 32 + 6 = 38, but (25)₁₆ = 32 + 5 = 37; decimal 38 in hex is 26.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-262","question":"What is (A0)₁₆ − (3F)₁₆, written in hexadecimal?","options":["71","5F","61","6F"],"answer":2,"explanation":"A0 = 160 and 3F = 63, so the difference is 97 = 6 × 16 + 1 = (61)₁₆. Forgetting the borrow taken from the 16s place gives the trap answer 71.","difficulty":"hard","source":"SSC CGL · IBPS SO IT Officer"},
  {"id":"comp-awareness-263","question":"What is (567)₈ + (234)₈, written in octal?","options":["801","1013","1023","1033"],"answer":2,"explanation":"7 + 4 = 11 = 13₈ (write 3, carry 1); 6 + 3 + 1 = 10 = 12₈ (write 2, carry 1); 5 + 2 + 1 = 8 = 10₈. Result (1023)₈ = 531 = 375 + 156; 801 is plain decimal addition.","difficulty":"very-hard","source":"SSC CGL · IBPS SO IT Officer"},
  {"id":"comp-awareness-264","question":"When the digits 8 and 5 are added in 8421 BCD, the 4-bit sum 1101 is not a valid BCD digit. How is it corrected, and what is the final BCD result?","options":["Add 0110, giving 0001 0011","Add 0011, giving 0001 0011","Add 0110, giving 0000 1101","Add 1010, giving 0001 0011"],"answer":0,"explanation":"A BCD digit sum above 9 is corrected by adding 6 (0110): 1101 + 0110 = 1 0011, so the result is 0001 0011, i.e. 13. Adding 3 is the Excess-3 correction.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-265","question":"What is the minimum number of bits needed to store every whole number from 0 to 9999 in pure binary?","options":["13","16","12","14"],"answer":3,"explanation":"2¹³ = 8192 is less than 9999, but 2¹⁴ = 16,384 covers it, so 14 bits are needed. 16 bits is what four BCD digits would take.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-266","question":"The value −6 is 1010 in 4-bit two's complement. When it is sign-extended to 8 bits, the result is:","options":["00001010","11111010","10001010","11110110"],"answer":1,"explanation":"Sign extension copies the sign bit into every new high position: 1111 1010, which is still −6. Padding with zeros would give +10, and 11110110 is −10.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-267","question":"The 8-bit two's-complement value 11101000 (−24) is shifted right by two places using an ARITHMETIC shift. What is the result?","options":["00111010","11111000","10100000","11111010"],"answer":3,"explanation":"An arithmetic right shift copies the sign bit into the vacated places: 11101000 → 11110100 → 11111010 = −6, i.e. −24 ÷ 4. A logical shift would insert zeros and give 00111010 = 58.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-268","question":"When two n-bit two's-complement numbers are added, overflow has occurred exactly when:","options":["Both operands have the same sign and the result has the opposite sign","A carry comes out of the most significant bit position during the addition","The operands have opposite signs and the result comes out negative","The sign bit of the result is 1, whatever the signs of the operands"],"answer":0,"explanation":"Overflow is possible only when both operands share a sign, and it shows as a result of the other sign. A carry out of the MSB alone is normal (e.g. −1 + 1) and is simply discarded.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-269","question":"Rotary shaft encoders and Karnaugh-map labels use Gray code mainly because:","options":["It needs fewer bits than pure binary to cover the same range","Successive values differ in exactly one bit, avoiding false readings","Each decimal digit is coded separately, which eases display output","It carries a built-in parity bit, so single-bit errors are detected"],"answer":1,"explanation":"Adjacent Gray codes differ in a single bit, so a sensor caught between two positions cannot produce a wildly wrong code. It uses as many bits as binary and has no parity bit.","difficulty":"moderate","source":"SSC CGL · IBPS SO IT Officer"},
  {"id":"comp-awareness-270","question":"Which code is self-complementing, so that inverting every bit of a digit's code gives the code of its 9's complement?","options":["8421 BCD","Gray code","Excess-3","7-bit ASCII"],"answer":2,"explanation":"Excess-3 codes digit d as d + 3; inverting gives 15 − (d + 3) = (9 − d) + 3, the Excess-3 code of 9 − d. For example 2 = 0101 inverts to 1010 = 7.","difficulty":"moderate","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-271","question":"The hexadecimal number 3FA is written in binary without leading zeros. How many bits does it have?","options":["12","10","11","9"],"answer":1,"explanation":"3FA = 0011 1111 1010; dropping the two leading zeros of the first hex digit leaves 11 1111 1010, which is 10 bits (its value 1018 lies between 512 and 1023).","difficulty":"hard","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-272","question":"The full contents of a 64-bit register are written out once in hexadecimal and once in octal. At most how many digits does each form need?","options":["16 and 22","16 and 21","8 and 22","16 and 24"],"answer":0,"explanation":"A hex digit holds 4 bits, so 64 ÷ 4 = 16; an octal digit holds 3 bits, so 64 ÷ 3 = 21.33, rounded up to 22 (the top octal digit holds just one bit).","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-273","question":"725 − 248 is worked out by adding the 10's complement of 248 to 725 and dropping the end carry. What are the 10's complement and the final result?","options":["751 and 477","752 and 476","751 and 476","752 and 477"],"answer":3,"explanation":"10's complement of 248 = 1000 − 248 = 752; 725 + 752 = 1477, and dropping the end carry leaves 477. 751 is only the 9's complement.","difficulty":"very-hard","source":"SSC CGL · IBPS SO IT Officer"},
  {"id":"comp-awareness-274","question":"What is (0.8)₁₆ + (0.4)₈, written in decimal?","options":["1.2","0.75","1","0.625"],"answer":2,"explanation":"(0.8)₁₆ = 8/16 = 0.5 and (0.4)₈ = 4/8 = 0.5, so the sum is exactly 1; reading the digits as decimal gives the trap 1.2.","difficulty":"hard","source":"SSC CGL · IBPS SO IT Officer"},
  {"id":"comp-awareness-275","question":"What is the sum of the largest value a 4-bit UNSIGNED number can hold and the smallest value a 4-bit TWO'S-COMPLEMENT number can hold?","options":["23","7","−1","8"],"answer":1,"explanation":"Unsigned 4 bits go up to 1111 = 15; 4-bit two's complement goes down to 1000 = −8; 15 + (−8) = 7. Taking −7 or +8 by mistake gives 8 or 23.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-276","question":"A cache takes 5 ns per access and main memory 80 ns. The cache is always checked first, and on a miss main memory is then read, so a miss costs 85 ns. What hit ratio gives an average access time of 13 ns?","options":["0.85","0.95","0.80","0.90"],"answer":3,"explanation":"Average = 5 + (1 − h) × 80 = 13, so (1 − h) × 80 = 8 and h = 0.90. Treating a miss as only 80 ns (parallel lookup) would give about 0.89, not any other option.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-277","question":"A direct-mapped cache has 128 lines. Main-memory block number 1000 is placed in which cache line (lines numbered from 0)?","options":["7","104","8","40"],"answer":1,"explanation":"Direct mapping uses line = block mod number of lines = 1000 mod 128 = 1000 − 896 = 104. The quotient 7 becomes part of the tag, not the line number.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-278","question":"A 64 KB direct-mapped cache uses 16-byte blocks, and the processor issues 32-bit byte addresses. How is each address split?","options":["Tag 12, index 16, offset 4","Tag 18, index 10, offset 4","Tag 16, index 12, offset 4","Tag 16, index 14, offset 2"],"answer":2,"explanation":"16-byte blocks need a 4-bit offset; 64 KB ÷ 16 B = 4096 lines need a 12-bit index; the tag is the remaining 32 − 12 − 4 = 16 bits.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-279","question":"Which cache-mapping technique lets any memory block be placed in any cache line, at the cost of comparing its tag with every line at once?","options":["Fully associative mapping","Direct mapping","2-way set-associative mapping","Write-through mapping"],"answer":0,"explanation":"Fully associative mapping allows any block anywhere, so all tags must be searched in parallel. Direct mapping fixes one line per block, and set-associative limits the choice to one set; write-through is a write policy, not a mapping.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-280","question":"A loop counter is read and updated on every pass of a loop, and so it stays in the cache. Which property of programs does this exploit?","options":["Spatial locality","Temporal locality","Memory interleaving","Write-back buffering"],"answer":1,"explanation":"Temporal locality means an item used now is likely to be used again soon, as a loop counter is. Spatial locality concerns neighbouring addresses, such as successive array elements.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-281","question":"When the CPU reads a word from main memory, which two registers hold the address being accessed and the data that arrives?","options":["MDR holds the address; MAR receives the data","PC holds the address; IR receives the data","IR holds the address; the accumulator receives the data","MAR holds the address; MDR receives the data"],"answer":3,"explanation":"The Memory Address Register holds the location placed on the address bus, and the Memory Data (Buffer) Register latches the word that comes back. The PC only points to the next instruction.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-282","question":"A processor has a 16-bit data bus and moves one word on each bus cycle at 8 MHz. What is the maximum data transfer rate?","options":["8 million bytes per second","16 million bytes per second","128 million bytes per second","32 million bytes per second"],"answer":1,"explanation":"Each cycle moves 16 bits = 2 bytes, so 8 × 10⁶ cycles/s × 2 bytes = 16 × 10⁶ bytes/s. 128 million is the figure in bits per second.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-283","question":"A 4K × 8 memory is to be built from 1K × 4 RAM chips. How many chips are needed, and how many address lines does the full memory require?","options":["4 chips and 12 address lines","8 chips and 10 address lines","8 chips and 12 address lines","16 chips and 12 address lines"],"answer":2,"explanation":"Chips = (4K × 8) ÷ (1K × 4) = 8 (two side by side for 8-bit width, four rows for 4K words). 4K = 2¹² locations needs 12 address lines; 10 lines address only one 1K chip.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-284","question":"Which pairing of ROM type and erasing method is WRONG?","options":["PROM – written once by the user and then cannot be erased","EPROM – erased by ultraviolet light through a quartz window","EEPROM – erased and rewritten electrically, byte by byte","Flash – erased only by ultraviolet light, whole chip at once"],"answer":3,"explanation":"Flash memory is a kind of EEPROM erased electrically, usually in blocks; only EPROM needs ultraviolet light. The other three pairings are correct.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-285","question":"A hard disk has 4 platters with both surfaces used, 1000 tracks per surface, 500 sectors per track and 512 bytes per sector. What is its capacity?","options":["1,024,000,000 bytes","2,048,000,000 bytes","4,096,000,000 bytes","256,000,000 bytes"],"answer":1,"explanation":"4 platters × 2 surfaces = 8 surfaces; 8 × 1000 × 500 × 512 = 2,048,000,000 bytes. Counting only one surface per platter gives 1,024,000,000.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-286","question":"On a multi-platter hard disk, a 'cylinder' is:","options":["The set of tracks at the same arm position on every surface","The set of sectors at the same angle on a single surface","One complete track on the top surface of the top platter","The group of sectors the OS handles as one allocation unit"],"answer":0,"explanation":"All heads move together, so the tracks under them at one arm position form a cylinder and can be read without a seek. A group of sectors used as an allocation unit is a cluster.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-287","question":"A Blu-ray disc holds several times more data than a DVD of the same size mainly because it:","options":["Spins much faster, so more data passes under the head","Records on both faces of the disc by default","Uses a shorter-wavelength blue-violet laser, allowing smaller pits","Stores data magnetically instead of as pits and lands"],"answer":2,"explanation":"A 405 nm blue-violet laser focuses to a smaller spot than a DVD's red laser, so pits and track spacing shrink and density rises. Speed and sides do not explain the basic capacity per layer.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-288","question":"A bank keeps nightly backups that are rarely read and are always restored in full. Which medium suits this, and why is it poor for frequent random lookups?","options":["SSD – its flash cells wear out after repeated random reads","Hard disk – its heads can only move from outer to inner tracks","Blu-ray – each disc can be read only a fixed number of times","Magnetic tape – it must be wound past earlier data to reach a record"],"answer":3,"explanation":"Tape is cheap, high-capacity sequential-access storage, ideal for bulk backup but slow to reach a single record. Flash wears out from writes, not reads, and disk heads seek in both directions.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-289","question":"A program executes 2 × 10⁹ instructions with an average of 1.5 clock cycles per instruction on a 3 GHz processor. How long does it take to run?","options":["1 second","0.67 second","1.5 seconds","4.5 seconds"],"answer":0,"explanation":"Time = instructions × CPI ÷ clock rate = 2 × 10⁹ × 1.5 ÷ (3 × 10⁹) = 1 s. Ignoring the CPI gives 0.67 s.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-290","question":"40% of a program's running time is spent in a routine that is then made 4 times faster; the rest is unchanged. By Amdahl's law, what is the overall speedup, to two decimals?","options":["1.60","2.50","1.43","1.30"],"answer":2,"explanation":"New time = 0.6 + 0.4 ÷ 4 = 0.7 of the old, so speedup = 1 ÷ 0.7 ≈ 1.43. The untouched 60% limits the gain no matter how fast the routine becomes.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-291","question":"A keyboard controller alerts the CPU only when a key is actually pressed, instead of the CPU checking its status again and again. This technique is called:","options":["Programmed I/O (polling)","Direct memory access","Memory-mapped I/O","Interrupt-driven I/O"],"answer":3,"explanation":"In interrupt-driven I/O the device raises an interrupt when it needs service, so the CPU does other work meanwhile. Polling is the repeated checking that this avoids.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-292","question":"Which statement correctly describes memory-mapped I/O?","options":["Device registers get addresses in the memory space and are used with ordinary load/store instructions","Devices have a separate address space and need special IN and OUT instructions to be accessed","A device copies whole blocks into RAM without the CPU and interrupts only when finished","The CPU keeps reading a device's status register in a loop until the device is ready"],"answer":0,"explanation":"Memory-mapped I/O places device registers in the normal address space. Separate IN/OUT instructions describe isolated (port-mapped) I/O; the other two describe DMA and polling.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-293","question":"In a paged virtual-memory system, the translation lookaside buffer (TLB) holds:","options":["Recently used data words fetched from main memory","Recently used page-number-to-frame-number translations","Pages that have been swapped out to the disk","The list of free frames in main memory"],"answer":1,"explanation":"The TLB is a small fast cache of page-table entries, so most address translations skip the page-table lookup in memory. Data words are kept in the ordinary data cache.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-294","question":"A system has 32-bit virtual addresses, 4 KB pages and 4-byte page-table entries. How large is one process's single-level page table?","options":["1 MB","16 KB","4 MB","4 GB"],"answer":2,"explanation":"Offset = 12 bits, so there are 2³² ÷ 2¹² = 2²⁰ pages; 2²⁰ entries × 4 bytes = 4 MB. 1 MB counts entries instead of bytes.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-295","question":"A TLB lookup takes 10 ns and a memory access 100 ns, and the TLB hit ratio is 90%. With a single-level page table, what is the effective memory access time?","options":["110 ns","129 ns","210 ns","120 ns"],"answer":3,"explanation":"Hit: 10 + 100 = 110 ns; miss: 10 + 100 (page table) + 100 (data) = 210 ns. Average = 0.9 × 110 + 0.1 × 210 = 99 + 21 = 120 ns.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-296","question":"The small coin-cell battery on a PC motherboard keeps power supplied to:","options":["The CMOS memory that holds the clock and BIOS settings","The BIOS program code stored in flash ROM","The L1 cache, so the processor starts faster","The RAM, so open files survive a shutdown"],"answer":0,"explanation":"Settings such as date, time and boot order sit in a tiny CMOS RAM with the real-time clock, which needs the battery; the BIOS code itself is in non-volatile flash.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-297","question":"Why can a disk partitioned with the older MBR scheme and 512-byte sectors use only about 2.2 TB of space?","options":["MBR allows only four primary partitions of 512 GB each","MBR stores sector numbers in 32 bits, and 2³² × 512 bytes ≈ 2.2 TB","MBR relies on FAT32, whose clusters cannot cover more than 2 TB","MBR stores sector numbers in 16 bits, and 2¹⁶ × 512 bytes ≈ 2.2 TB"],"answer":1,"explanation":"MBR partition entries keep 32-bit sector addresses, so 2³² × 512 B = 2,199,023,255,552 bytes is the ceiling; GPT uses 64-bit addresses. 2¹⁶ × 512 B is only 32 MB.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-298","question":"In a laser printer, the page image is first formed as:","options":["Ink droplets sprayed through tiny nozzles onto the paper","Heat applied to specially coated paper by a print head","An electrostatic charge pattern on a photosensitive drum","Pins striking an inked ribbon against the paper"],"answer":2,"explanation":"The laser discharges parts of a charged drum; toner sticks to that pattern, is transferred to paper and fused by heat. The other options describe inkjet, thermal and dot-matrix printers.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-awareness-299","question":"Which touchscreen technology senses the electrical conductivity of a finger, and so does not respond to an ordinary plastic stylus?","options":["Resistive","Capacitive","Infrared grid","Optical camera-based"],"answer":1,"explanation":"A capacitive screen detects the change in charge caused by a conductive finger. Resistive screens react to pressure from anything, and infrared or optical screens detect any object breaking the light.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-300","question":"Which of these printers is an IMPACT printer?","options":["Laser printer","Inkjet printer","Thermal printer","Daisy-wheel printer"],"answer":3,"explanation":"A daisy-wheel printer strikes a character petal against an inked ribbon, like dot-matrix printers. Laser, inkjet and thermal printers form the image without striking the paper.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-awareness-301","question":"A process that was blocked waiting for a disk read is told that the read has finished. To which state does it move next?","options":["Running","Ready","Terminated","New"],"answer":1,"explanation":"Completion of I/O moves a process from waiting to ready; it runs only when the scheduler dispatches it. It does not jump straight back to running.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-302","question":"Processes P1, P2 and P3 arrive at time 0 in that order with CPU bursts of 5, 3 and 1 ms. Under Round Robin with a time quantum of 2 ms, what is the average waiting time?","options":["7.33 ms","3.67 ms","4.33 ms","5.00 ms"],"answer":2,"explanation":"Order: P1 0–2, P2 2–4, P3 4–5, P1 5–7, P2 7–8, P1 8–9. Waiting = completion − burst: P1 9 − 5 = 4, P2 8 − 3 = 5, P3 5 − 1 = 4; average 13 ÷ 3 ≈ 4.33 ms. 7.33 is the average turnaround time.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-303","question":"Four processes have (arrival, burst) times P1 (0, 7), P2 (2, 4), P3 (4, 1) and P4 (5, 4) in ms. Under pre-emptive Shortest Remaining Time First, what is the average waiting time?","options":["4 ms","3.5 ms","2.75 ms","3 ms"],"answer":3,"explanation":"Schedule: P1 0–2, P2 2–4, P3 4–5, P2 5–7, P4 7–11, P1 11–16. Waits: P1 9, P2 1, P3 0, P4 2, so the average is 12 ÷ 4 = 3 ms. Non-pre-emptive SJF would give 4 ms.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-304","question":"Under priority scheduling, a low-priority process may wait for ever. Which technique fixes this by slowly raising the priority of processes that have waited long?","options":["Aging","Thrashing","Spooling","Swapping"],"answer":0,"explanation":"Aging increases a waiting process's priority over time, so starvation cannot last indefinitely. Thrashing is excessive paging; spooling and swapping are unrelated.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-305","question":"Many short processes sit idle behind one long CPU-bound process, lowering device and CPU utilisation. This 'convoy effect' is typical of which scheduling algorithm?","options":["Round Robin","Shortest Remaining Time First","First-Come, First-Served","Multilevel feedback queue"],"answer":2,"explanation":"Non-pre-emptive FCFS lets a long job hold the CPU while short jobs queue behind it. Round Robin and SRTF pre-empt, and feedback queues demote long jobs.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-306","question":"Which page-replacement algorithm can suffer from Belady's anomaly, where giving a process MORE frames produces MORE page faults?","options":["LRU","Optimal (OPT)","Both LRU and Optimal","FIFO"],"answer":3,"explanation":"FIFO is not a stack algorithm, so a larger memory need not contain the pages a smaller one holds, and faults can rise. LRU and Optimal are stack algorithms and never show the anomaly.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-307","question":"A process has 3 page frames, all empty at first, and refers to pages 7, 0, 1, 2, 0, 3, 0, 4, 2, 3. How many page faults occur under the Optimal (OPT) algorithm?","options":["7","6","8","9"],"answer":1,"explanation":"OPT evicts the page used farthest in future: faults on 7, 0, 1, 2 (evict 7), 3 (evict 1) and 4 (evict 0); the rest hit, so 6 faults. LRU gives 8 and FIFO 9 on this string.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-308","question":"A system has 12 tape drives. P0 holds 5 (maximum need 10), P1 holds 2 (maximum 4) and P2 holds 2 (maximum 9). Under the Banker's algorithm, which is a safe sequence?","options":["<P0, P1, P2>","<P2, P1, P0>","<P1, P0, P2>","No safe sequence exists"],"answer":2,"explanation":"Free = 12 − 9 = 3. P1 needs 2, finishes, free 5; P0 needs 5, finishes, free 10; P2 needs 7, finishes. P0 cannot go first (needs 5 with only 3 free), and P2 cannot run before P0.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-309","question":"Four processes share identical units of one resource, and each may need up to 3 units at once. What is the least number of units that guarantees no deadlock?","options":["8","12","10","9"],"answer":3,"explanation":"Worst case: each holds 2 units and waits for one more, using 4 × 2 = 8. One extra unit lets someone finish, so n(k − 1) + 1 = 4 × 2 + 1 = 9 units suffice.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-310","question":"A counting semaphore starts at 7. Then 20 wait (P) operations and 15 signal (V) operations are performed on it. What is its final value?","options":["2","12","−8","5"],"answer":0,"explanation":"Each P subtracts 1 and each V adds 1: 7 − 20 + 15 = 2. A negative value would mean processes are blocked on it.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-311","question":"Which of these is NOT one of the three requirements a correct critical-section solution must meet?","options":["Mutual exclusion","Progress","Bounded waiting","Equal CPU time for every process"],"answer":3,"explanation":"A critical-section solution must give mutual exclusion, progress and bounded waiting. Fair CPU sharing is a scheduling goal, not part of the critical-section problem.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-312","question":"How does a microkernel operating system differ from a monolithic one?","options":["It runs drivers and file systems inside the kernel for maximum speed","It keeps only core services such as IPC and basic scheduling in kernel mode","It has no kernel mode at all, so every program runs with full privileges","It loads the whole operating system into ROM so it cannot be modified"],"answer":1,"explanation":"A microkernel keeps minimal services in kernel mode and runs drivers and file systems as user-space servers, gaining reliability at some speed cost. Putting everything in the kernel describes a monolithic design.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-313","question":"In the many-to-one threading model (many user-level threads mapped to one kernel thread), what happens when one thread makes a blocking system call?","options":["Only that thread blocks and the others keep running","The kernel creates a new kernel thread for the rest","The blocking call is converted into a non-blocking one","The whole process blocks until the call returns"],"answer":3,"explanation":"The kernel sees only one schedulable thread, so if it blocks, every user-level thread in the process stops. One-to-one models avoid this.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-314","question":"The main purpose of multiprogramming in an operating system is to:","options":["Keep the CPU busy by switching jobs when one waits for I/O","Run one program on several processors at once","Let one user run several windows on the same screen","Divide a large program into pages that fit in memory"],"answer":0,"explanation":"Several jobs are kept in memory; when one waits for I/O, the CPU switches to another, raising utilisation. Running on several processors is multiprocessing.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-315","question":"Which file-allocation method allows fast direct access to any block but suffers from external fragmentation?","options":["Linked allocation","Indexed allocation","Contiguous allocation","FAT-chained allocation"],"answer":2,"explanation":"Contiguous files let block k be found at start + k, but free space breaks into holes. Linked (and FAT-chained) allocation needs a chain walk, and indexed allocation avoids external fragmentation.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-316","question":"Which Windows file system supports file-level permissions, journaling for crash recovery and single files larger than 4 GB?","options":["FAT32","FAT16","exFAT","NTFS"],"answer":3,"explanation":"NTFS offers access-control lists, a journal and very large files. exFAT allows large files but has no permissions or journal; FAT32 caps files just under 4 GB.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-317","question":"In a UNIX-like file system, a file's inode stores all of the following EXCEPT the file's:","options":["Size","Name","Access permissions","Pointers to its data blocks"],"answer":1,"explanation":"Names live in directory entries that map a name to an inode number; that is why one inode can have several hard-linked names. Size, permissions and block pointers are in the inode.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-318","question":"A file report.txt has one hard link and one symbolic link pointing to it. The original name report.txt is then deleted. What happens?","options":["The symbolic link breaks, but the hard link still opens the data","The hard link breaks, but the symbolic link still opens the data","Both links break because the data is erased at once","Both links keep working because links copy the data"],"answer":0,"explanation":"A hard link is another name for the same inode, so the data survives while any hard link remains. A symbolic link stores only the path, which now points nowhere.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-319","question":"In Linux, the command chmod 754 file gives the file which permission string?","options":["rwxrw-r--","rwxr-xr-x","r-xrwxr--","rwxr-xr--"],"answer":3,"explanation":"Each digit is r = 4, w = 2, x = 1 for owner, group and others: 7 = rwx, 5 = r-x, 4 = r--. 755 would give r-x to others as well.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-320","question":"Match the Windows shortcut with its action: 1. Windows + L 2. Windows + D 3. Alt + F4 4. Alt + Tab; a. Show the desktop b. Close the active window c. Switch between open windows d. Lock the computer","options":["1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b","1-d, 2-a, 3-b, 4-c","1-d, 2-b, 3-a, 4-c"],"answer":2,"explanation":"Windows + L locks, Windows + D shows the desktop, Alt + F4 closes the active window and Alt + Tab switches between open windows.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-321","question":"A program calls fork() three times in a row, with no conditions, and every call succeeds. How many processes exist in total, counting the original?","options":["8","6","4","7"],"answer":0,"explanation":"Each fork doubles the running processes: 1 → 2 → 4 → 8. Seven of them are children; 6 comes from wrongly adding 2 per call.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-322","question":"A user program divides an integer by zero. What does the processor generate?","options":["A hardware interrupt from an external device controller","A trap (exception) raised by the CPU itself and handled by the OS","A system call deliberately requested by the program","A page fault serviced by loading a page from disk"],"answer":1,"explanation":"An error inside the running instruction raises a synchronous trap, and the OS's handler takes over (often ending the program). Interrupts come from external devices; a system call is a deliberate request.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-323","question":"Why do processors provide separate user mode and kernel (supervisor) mode?","options":["To let user programs run faster by skipping security checks","To let two operating systems run at the same time on one CPU","To stop user programs from directly running privileged instructions","To keep a backup copy of the kernel in case the first one fails"],"answer":2,"explanation":"Instructions such as I/O or changing memory protection run only in kernel mode, so a faulty or malicious program must ask the OS through a system call instead.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-324","question":"Which scheduler swaps partly executed processes out of memory to the disk, and later back in, to adjust the degree of multiprogramming?","options":["Long-term scheduler","Medium-term scheduler","Short-term scheduler","Dispatcher"],"answer":1,"explanation":"The medium-term scheduler handles swapping. The long-term scheduler admits new jobs, and the short-term scheduler (with the dispatcher) picks the next ready process for the CPU.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-325","question":"Defragmenting a hard disk drive usually speeds up file access because it:","options":["Moves each file's blocks next to one another, cutting head movement","Compresses files so that fewer sectors have to be read","Removes viruses that hide in the unused sectors of the disk","Copies frequently used programs permanently into the RAM"],"answer":0,"explanation":"Scattered fragments force many seeks; placing a file's blocks contiguously reduces them. Defragmenting neither compresses data nor scans for viruses.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-326","question":"Match the OSI layer with the name of its data unit: 1. Transport 2. Network 3. Data link 4. Physical; a. Frame b. Bits c. Segment d. Packet","options":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":1,"explanation":"Transport layer data units are segments (datagrams for UDP), network layer units are packets, data link units are frames, and the physical layer carries bits.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-327","question":"The four-layer TCP/IP model has a single Application layer. Which OSI layers does it combine?","options":["Application, Presentation and Session","Application and Presentation only","Application, Session and Transport","Presentation, Session and Network"],"answer":0,"explanation":"TCP/IP's Application layer covers OSI layers 7, 6 and 5; Transport maps to OSI Transport, Internet to Network, and Network Access to Data Link plus Physical.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-328","question":"A computer knows the IP address of another machine on the same LAN but needs that machine's MAC address to send it a frame. Which protocol does it use?","options":["DNS","DHCP","ARP","RARP"],"answer":2,"explanation":"ARP broadcasts 'who has this IP?' and the owner replies with its MAC address. RARP works in the opposite direction, and DNS maps names to IP addresses.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-329","question":"A home router lets ten devices with private IP addresses share a single public IP address on the internet. Which technique makes this possible?","options":["Dynamic Host Configuration Protocol","Network Address Translation","Address Resolution Protocol","Domain Name System"],"answer":1,"explanation":"NAT (port address translation) rewrites private source addresses to the one public address and uses port numbers to send replies back to the right device. DHCP only hands out the private addresses.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-330","question":"The class C network 200.10.5.0 must be split into at least 6 subnets, each as large as possible. Which mask is used, and how many usable hosts does each subnet get?","options":["255.255.255.192 with 62 hosts each","255.255.255.240 with 14 hosts each","255.255.255.224 with 32 hosts each","255.255.255.224 with 30 hosts each"],"answer":3,"explanation":"6 subnets need 3 borrowed bits (2³ = 8), giving /27 = 255.255.255.224. That leaves 5 host bits: 2⁵ − 2 = 30 usable hosts; 32 forgets the network and broadcast addresses.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-331","question":"How many usable host addresses does a /20 IPv4 network provide?","options":["4096","4094","2046","1022"],"answer":1,"explanation":"A /20 leaves 32 − 20 = 12 host bits: 2¹² = 4096 addresses, minus the network and broadcast addresses = 4094.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-332","question":"Which single CIDR block covers exactly the four networks 192.168.8.0/24, 192.168.9.0/24, 192.168.10.0/24 and 192.168.11.0/24?","options":["192.168.8.0/21","192.168.0.0/22","192.168.8.0/22","192.168.8.0/23"],"answer":2,"explanation":"Third octets 8–11 are 000010xx, sharing their first 6 bits, so the prefix is 16 + 6 = 22 bits: 192.168.8.0/22. A /21 would also take in 12–15, and a /23 covers only two of them.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-333","question":"Which of these hosts is on the SAME subnet as 172.16.5.200/26?","options":["172.16.5.190","172.16.5.250","172.16.5.130","172.16.6.200"],"answer":1,"explanation":"A /26 splits the last octet into blocks of 64: 0–63, 64–127, 128–191 and 192–255. 200 and 250 both fall in 192–255; 190 and 130 are in 128–191, and 172.16.6.x is a different network.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-334","question":"The IPv4 address 224.0.0.5 belongs to which class, and what is that class used for?","options":["Class C – unicast hosts on small networks","Class E – reserved for experimental use","Class B – unicast hosts on medium networks","Class D – multicast to a group of hosts"],"answer":3,"explanation":"First octets 224–239 form class D, used for multicast groups. Class C runs from 192 to 223 and class E from 240 to 255.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-335","question":"A router has three interfaces, and each is connected to a separate switch serving 8 PCs, with no VLANs. How many broadcast domains are there?","options":["1","24","3","27"],"answer":2,"explanation":"Routers do not forward broadcasts, so each router interface marks off one broadcast domain: 3. Switches split collision domains, not broadcast domains.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-336","question":"Wired Ethernet uses CSMA/CD, but Wi-Fi uses CSMA/CA. What is the main reason?","options":["A wireless station cannot reliably sense a collision while it is transmitting","Radio signals never collide, so wireless stations only need to avoid queues","Wi-Fi passes a token between stations, so collision detection is not needed","Collision detection works only on fibre, which Wi-Fi access points do not use"],"answer":0,"explanation":"A radio's own strong transmission drowns out weaker signals, and hidden stations may be out of range, so collisions cannot be detected; Wi-Fi tries to avoid them with backoff and acknowledgements instead.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-337","question":"A file of 10⁶ bytes is sent over a 2 Mbps link whose propagation delay is 20 ms. Ignoring other overheads, how long after sending starts does the last bit arrive?","options":["0.52 s","4.2 s","4 s","4.02 s"],"answer":3,"explanation":"Transmission time = 8 × 10⁶ bits ÷ 2 × 10⁶ bps = 4 s; the last bit then needs 20 ms to travel, so 4.02 s. Using bytes instead of bits gives 0.52 s.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-338","question":"How does single-mode optical fibre differ from multimode fibre?","options":["It has a wider core and carries many light paths, so it suits short links","It carries electrical signals instead of light, so it resists bending","It has a narrower core and carries one light path, so it suits long links","It works only with LEDs, which makes it cheaper over long distances"],"answer":2,"explanation":"Single-mode fibre's very thin core allows a single light mode, avoiding modal dispersion, so it carries signals far, usually with lasers. Multimode has a wider core and is used for short runs.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-339","question":"Why are the pairs of wires in a twisted-pair cable twisted around each other?","options":["To make the cable stronger so it can be pulled through walls","To reduce electromagnetic interference and crosstalk between pairs","To let the same pair carry light as well as electrical signals","To increase the resistance of the wire and save power"],"answer":1,"explanation":"Twisting makes noise induce nearly equal and opposite effects in the two wires, which cancel at the receiver, and it limits crosstalk from neighbouring pairs.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-340","question":"Match the protocol with its default port: 1. SSH 2. Telnet 3. POP3 4. IMAP; a. 110 b. 143 c. 23 d. 22","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-a, 3-c, 4-b"],"answer":2,"explanation":"SSH uses 22 and the older unencrypted Telnet uses 23; POP3 uses 110 and IMAP uses 143.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-341","question":"A manager reads e-mail on a phone and a laptop and wants both to show the same folders and the same read/unread status. Which protocol should the mail client use to retrieve mail?","options":["POP3","SMTP","IMAP","MIME"],"answer":2,"explanation":"IMAP keeps mail and folders on the server and syncs status to every device. POP3 typically downloads and removes mail, SMTP only sends, and MIME is a message format.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-342","question":"Which standard lets an e-mail carry attachments such as images, PDFs and text in non-English scripts?","options":["MIME","SNMP","POP3","SMTP"],"answer":0,"explanation":"Multipurpose Internet Mail Extensions define content types and encodings so binary files and non-ASCII text travel in mail. SMTP only transports the message.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-343","question":"In the URL https://www.example.co.in:8080/loans/apply.html?id=7, what are the port number used and the top-level domain?","options":["443 and .co.in","8080 and .co","80 and .in","8080 and .in"],"answer":3,"explanation":"An explicit ':8080' overrides HTTPS's default port 443. The top-level domain is the last label, .in; .co.in is a second-level domain under it.","difficulty":"very-hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-344","question":"A browser shows 'HTTP 404'. What does this status code tell the user?","options":["The server could not be reached at all","The server was reached but the requested page was not found","The user is not allowed to view the requested page","The server crashed while it was handling the request"],"answer":1,"explanation":"4xx codes are client-side errors; 404 means the server answered but has nothing at that path. Forbidden is 403, a server failure is 5xx, and an unreachable server returns no HTTP code.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-345","question":"Which DNS record type tells other mail servers which server accepts e-mail for a domain?","options":["A","CNAME","MX","PTR"],"answer":2,"explanation":"An MX (mail exchanger) record names a domain's mail server. A maps a name to an IPv4 address, CNAME makes an alias, and PTR does reverse lookups.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-346","question":"How does packet switching differ from circuit switching?","options":["A fixed path is reserved for the whole call before any data is sent","Data is sent in packets that may take different routes, with no path reserved","Every packet is sent to all nodes, and each node keeps only its own data","Data can be sent only when the line is idle for the entire session"],"answer":1,"explanation":"Packet switching shares links on demand and routes each packet independently, while circuit switching (like the old telephone network) reserves a dedicated path first.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-347","question":"Live video calls usually send their media over UDP rather than TCP. Why?","options":["UDP encrypts the stream, while TCP sends it as plain text","UDP guarantees delivery in order, which video needs","Retransmitting late packets is useless, and UDP avoids that delay","TCP cannot carry more than one stream on a connection"],"answer":2,"explanation":"A resent video frame arrives too late to play, and TCP's retransmission and in-order delivery add delay. UDP itself gives no ordering or delivery guarantee and no encryption.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-348","question":"What does the Time to Live (TTL) field in an IPv4 packet header do?","options":["Sets the clock time at which the packet must be delivered","Is reduced by one at each router; the packet is dropped at zero","Counts how many times the packet has been retransmitted by TCP","Tells the receiver how long to keep the packet in its cache"],"answer":1,"explanation":"Each router decrements TTL and discards the packet when it reaches 0, so packets caught in routing loops cannot circulate forever; traceroute relies on this.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-349","question":"Tap-to-pay contactless cards and phones exchange data only within a few centimetres of the reader. Which technology do they use?","options":["Bluetooth","Infrared (IrDA)","Wi-Fi Direct","Near Field Communication"],"answer":3,"explanation":"NFC works over about 4 cm, which suits payments because accidental reading from far away is unlikely. Bluetooth and Wi-Fi Direct reach metres.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-350","question":"How long is an IPv6 address, and how many times may the shorthand '::' (a run of zero groups) appear in one written address?","options":["128 bits; it may appear only once","128 bits; it may appear any number of times","64 bits; it may appear only once","256 bits; it may appear at most twice"],"answer":0,"explanation":"IPv6 addresses are 128 bits (8 groups of 16). '::' can be used only once, because with two of them the reader could not tell how many zero groups each one hides.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-351","question":"Asha wants to send Ravi a message that only Ravi can read AND that Ravi can prove came from her. Which keys does she use?","options":["Her private key to sign and Ravi's public key to encrypt","Her public key to sign and Ravi's private key to encrypt","Ravi's public key to sign and her private key to encrypt","Her private key both to sign and to encrypt the message"],"answer":0,"explanation":"Signing uses the sender's private key (anyone can verify with her public key); confidentiality needs the receiver's public key, so only his private key can decrypt. Encrypting with her private key hides nothing, since her public key is public.","difficulty":"very-hard","source":"IBPS SO IT Officer · IBPS PO Mains"},
  {"id":"comp-awareness-352","question":"Which of these is an ASYMMETRIC (public-key) encryption algorithm?","options":["AES","DES","RSA","Triple DES"],"answer":2,"explanation":"RSA uses a public/private key pair. AES, DES and Triple DES are symmetric ciphers that use one shared secret key.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-353","question":"Which property of a cryptographic hash function means it is practically impossible to find two different inputs that give the same hash value?","options":["Pre-image resistance","Collision resistance","Avalanche effect","Key exchange"],"answer":1,"explanation":"Collision resistance is about finding any two inputs with equal hashes. Pre-image resistance means you cannot work back from a hash to an input, and the avalanche effect is a small input change flipping many output bits.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-354","question":"A distributed denial-of-service attack keeps a bank's website offline for hours. Which goal of the CIA security triad has mainly been attacked?","options":["Confidentiality","Integrity","Authentication","Availability"],"answer":3,"explanation":"DDoS floods stop legitimate users from reaching the service, an attack on availability; no data need be read (confidentiality) or altered (integrity). Authentication is not part of the triad.","difficulty":"moderate","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-355","question":"Which login method is genuine two-factor authentication?","options":["A password plus an answer to a secret security question","A fingerprint scan plus a face scan from the same phone","A password plus a one-time code sent to the phone","A PIN plus the user's date of birth typed on the next page"],"answer":2,"explanation":"Two factors must come from different categories: something you know (password) and something you have (the phone receiving the OTP). Two knowledge items or two biometrics are still a single factor type.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-356","question":"Match the attack with its description: 1. Vishing 2. Smishing 3. Spear phishing 4. Whaling; a. Fraud carried out through SMS texts b. Fraud aimed at top executives c. Fraud by voice telephone calls d. Fraud tailored to one particular person or group","options":["1-c, 2-a, 3-d, 4-b","1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-b, 4-d","1-c, 2-d, 3-a, 4-b"],"answer":0,"explanation":"Vishing is voice phishing, smishing uses SMS, spear phishing is aimed at a chosen target, and whaling is spear phishing aimed at senior executives.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-357","question":"Customers type their bank's correct web address but are silently taken to a fake site, because the DNS records they rely on have been tampered with. This attack is:","options":["Vishing","Pharming","Spear phishing","Keylogging"],"answer":1,"explanation":"Pharming redirects users through poisoned DNS or a modified hosts file, so even a correctly typed address leads to the fake site. Phishing, by contrast, needs the victim to click a misleading link.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-358","question":"An employee hides code in the payroll system that will delete salary records only if his own name is ever removed from the staff list. This is a:","options":["Worm","Rootkit","Adware","Logic bomb"],"answer":3,"explanation":"A logic bomb lies dormant until a set condition (a date or event) occurs and then does damage. A worm spreads itself, a rootkit hides malware, and adware shows advertisements.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-359","question":"A programmer at a bank rounds down the interest on lakhs of accounts and quietly moves the tiny leftover fractions into his own account. This fraud is called a:","options":["Salami attack","Phishing attack","Denial-of-service attack","Trojan horse"],"answer":0,"explanation":"A salami attack steals amounts too small to notice on each account but large in total. It needs no fake messages (phishing) and does not stop the service.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-360","question":"Malware changes parts of the operating system so that its own files and processes do not appear in file listings or the task manager. It is best described as a:","options":["Macro virus","Rootkit","Worm","Adware"],"answer":1,"explanation":"A rootkit hides itself (and often other malware) by subverting the OS's own reporting tools. Worms spread themselves, and macro viruses live in documents.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-361","question":"A virus rewrites its own code with a different encryption key on every infection, so that no fixed signature matches all its copies. It is a:","options":["Boot-sector virus","Macro virus","Polymorphic virus","Resident virus"],"answer":2,"explanation":"A polymorphic virus mutates its appearance to defeat signature-based scanners. Boot-sector and macro viruses are named for where they live, not how they disguise themselves.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-362","question":"A virus spreads through word-processor documents and runs automatically when an infected document is opened. It is a:","options":["Macro virus","Boot-sector virus","Logic bomb","Rootkit"],"answer":0,"explanation":"Macro viruses are written in an application's macro language and run when the document opens; that is why office programs disable macros in files from the internet by default.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-363","question":"Attackers exploit a software flaw that the vendor does not yet know about, so no patch exists. Such an attack is called a:","options":["Brute-force attack","Replay attack","Dictionary attack","Zero-day attack"],"answer":3,"explanation":"'Zero-day' means the defenders have had zero days to fix the flaw. Brute-force and dictionary attacks guess passwords, and a replay attack resends captured data.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-364","question":"Typing ' OR '1'='1 into the password box of a poorly written login page logs the attacker in without a password. Which attack is this?","options":["Cross-site scripting","SQL injection","Buffer overflow","Brute-force attack"],"answer":1,"explanation":"The input changes the meaning of the SQL query so its WHERE condition is always true. Parameterised queries prevent this; cross-site scripting injects browser scripts instead.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-365","question":"An attacker posts a comment containing JavaScript on a forum, and the script then runs in the browser of everyone who views that page. This is:","options":["SQL injection","Session fixation","Cross-site scripting","Clickjacking"],"answer":2,"explanation":"Stored cross-site scripting (XSS) makes the site deliver the attacker's script to other visitors, where it can steal session cookies. SQL injection targets the database, not the browser.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-366","question":"On a café's open Wi-Fi, an attacker secretly relays all traffic between a customer and her bank, reading and changing it on the way. This is a:","options":["Man-in-the-middle attack","Denial-of-service attack","Brute-force attack","Salami attack"],"answer":0,"explanation":"In a man-in-the-middle attack both sides think they talk directly to each other while the attacker sits between them. HTTPS with certificate checks is the main defence.","difficulty":"moderate","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-367","question":"A machine can try 1000 PINs per second. In the worst case, about how long does it take to find a 6-digit numeric PIN by trying every possibility?","options":["About 1.7 minutes","About 2.8 hours","About 10 seconds","About 16.7 minutes"],"answer":3,"explanation":"There are 10⁶ six-digit PINs; 10⁶ ÷ 1000 = 1000 s ≈ 16.7 minutes. This is why systems lock the account after a few wrong tries.","difficulty":"hard","source":"IBPS PO Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-368","question":"How does an intrusion prevention system (IPS) differ from an intrusion detection system (IDS)?","options":["An IPS sits inline and can block suspicious traffic, not just raise an alert","An IPS only records traffic for analysis later and never raises any alert","An IPS checks e-mail attachments, while an IDS checks only web pages","An IPS works on the user's PC, while an IDS works only on routers"],"answer":0,"explanation":"An IDS monitors and alerts; an IPS sits in the traffic path and drops or blocks what it judges malicious. Neither is limited to e-mail, web pages or a particular device.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-369","question":"A security team sets up a deliberately weak-looking decoy server, with no real data, to attract attackers and study their methods. It is a:","options":["Proxy server","Honeypot","Firewall","Sandbox"],"answer":1,"explanation":"A honeypot lures attackers so their tools and behaviour can be watched without risk to real systems. A sandbox isolates suspicious programs, and a firewall filters traffic.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-370","question":"A full backup is taken every Sunday night and an INCREMENTAL backup every other night. The disk fails on Thursday morning. Which backups are needed to restore the latest data?","options":["Sunday's full backup and Wednesday's incremental backup only","Wednesday's incremental backup only","Sunday's full backup and the Monday, Tuesday and Wednesday incrementals","Sunday's full backup only, since incrementals are never restored"],"answer":2,"explanation":"Each incremental holds only changes since the previous backup, so the full backup and every incremental after it are needed in order. Full + latest only works for differential backups.","difficulty":"very-hard","source":"IBPS SO IT Officer · IBPS PO Mains"},
  {"id":"comp-awareness-371","question":"A browser shows a padlock for https://example-bank.in. What does this padlock actually guarantee?","options":["The site is run by a genuine, licensed bank and is safe for all payments","The site has been scanned by the browser and found free of all malware","Traffic to the site is encrypted, and it holds a valid certificate for that domain","The site will never store or share any of your personal data"],"answer":2,"explanation":"TLS proves only that the connection is encrypted and that the server controls the domain named in its certificate; a phishing site can have a padlock too.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-372","question":"Which body issues and digitally signs the certificates that bind a public key to a website or a person?","options":["Domain name registrar","Internet service provider","Certificate Authority","Web browser maker"],"answer":2,"explanation":"A Certificate Authority verifies identity and signs the certificate with its own private key; browsers trust certificates that chain back to a trusted CA. A registrar only records domain ownership.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-373","question":"A bank makes its fingerprint scanner's matching threshold stricter. What is the expected effect?","options":["False acceptances rise and false rejections fall","Both false acceptances and false rejections fall","Both false acceptances and false rejections rise","False acceptances fall and false rejections rise"],"answer":3,"explanation":"A stricter threshold lets fewer impostors through (lower FAR) but also turns away more genuine users (higher FRR); the two rates trade off against each other.","difficulty":"very-hard","source":"IBPS SO IT Officer · IBPS PO Mains"},
  {"id":"comp-awareness-374","question":"Ransomware has encrypted every file on a branch's computers. What best lets the branch recover without paying the ransom?","options":["Running a disk defragmenter on the affected drives","Keeping recent backups stored offline, away from the network","Changing the passwords of every user account","Reinstalling the antivirus program on each computer"],"answer":1,"explanation":"Only a clean, recent backup the malware could not reach restores the data; new passwords or antivirus stop future damage but cannot decrypt files already encrypted.","difficulty":"moderate","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-375","question":"Hiding a secret message inside the pixel values of an ordinary-looking photograph, so that nobody suspects a message exists, is called:","options":["Cryptanalysis","Hashing","Steganography","Tokenisation"],"answer":2,"explanation":"Steganography conceals the existence of a message; cryptography conceals its meaning. Cryptanalysis is code-breaking, and hashing makes a fixed-size digest.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-376","question":"A relation R(A, B, C, D) has the functional dependencies AB → C, C → D and D → A. Which are ALL its candidate keys?","options":["AB, BC and BD","AB only","AB and BC only","B only"],"answer":0,"explanation":"B appears on no right side, so every key contains B, but B alone gives only B. AB → C → D gives ABCD; BC → D → A gives ABCD; BD → A, then AB → C gives ABCD. So AB, BC and BD are all minimal keys.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-377","question":"EMPLOYEE(EmpID, Name, DeptID, DeptName) has key EmpID, and DeptID → DeptName also holds. All values are atomic. What is the highest normal form the table satisfies?","options":["1NF","3NF","BCNF","2NF"],"answer":3,"explanation":"A single-attribute key rules out partial dependencies, so it is in 2NF. But EmpID → DeptID → DeptName is a transitive dependency of a non-key attribute, which breaks 3NF.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-378","question":"A relation is in Boyce–Codd Normal Form (BCNF) when:","options":["Every non-key attribute depends on the whole of every candidate key","For every non-trivial dependency X → Y, X is a superkey","No non-key attribute depends on another non-key attribute","Every attribute holds only atomic, single values"],"answer":1,"explanation":"BCNF demands that every determinant be a superkey, which is stricter than 3NF (3NF also allows X → Y when Y is a prime attribute). The other options describe 2NF, 3NF and 1NF ideas.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-379","question":"A CUSTOMER table keeps several phone numbers in one Phone column, separated by commas (for example '98xxxxxx01, 98xxxxxx02'). Which normal form does this break?","options":["Second normal form","Third normal form","Boyce–Codd normal form","First normal form"],"answer":3,"explanation":"1NF requires every column value to be atomic; a list of phone numbers in one cell is a repeating group. The fix is a separate CUSTOMER_PHONE table.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-380","question":"A relation R(A, B, C) has A as its only candidate key. How many superkeys does R have?","options":["4","3","7","1"],"answer":0,"explanation":"A superkey is any attribute set containing a key. Sets containing A: {A}, {A,B}, {A,C}, {A,B,C}, which makes 4. 7 counts every non-empty subset.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-381","question":"Table ACCOUNT has 5 rows and table NOMINEE has 4 rows. Three accounts match exactly one nominee each, and two accounts match none. How many rows does ACCOUNT LEFT OUTER JOIN NOMINEE on the account number return?","options":["3","20","7","5"],"answer":3,"explanation":"A left join keeps every row of the left table: 3 matched rows plus 2 unmatched rows padded with NULLs = 5. An inner join would return 3, and a cross join 20.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-382","question":"Table A has 6 rows and 3 columns, and table B has 4 rows and 2 columns. What does SELECT * FROM A, B (with no WHERE clause) return?","options":["10 rows and 5 columns","24 rows and 5 columns","24 rows and 6 columns","10 rows and 6 columns"],"answer":1,"explanation":"Listing two tables without a join condition forms the Cartesian product: 6 × 4 = 24 rows, each with 3 + 2 = 5 columns.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-383","question":"A column Bonus holds the values 10, 20, NULL and 30 in four rows. What does SELECT AVG(Bonus) return?","options":["20","15","NULL","60"],"answer":0,"explanation":"Aggregate functions skip NULLs, so AVG = (10 + 20 + 30) ÷ 3 = 20. Treating NULL as 0 and dividing by 4 gives the trap 15.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-384","question":"Which statement about DELETE and TRUNCATE in SQL is correct?","options":["TRUNCATE can remove selected rows with WHERE; DELETE always empties the whole table","DELETE removes the table structure as well, while TRUNCATE keeps the structure","DELETE can remove selected rows using WHERE; TRUNCATE empties the table but keeps its structure","Both DELETE and TRUNCATE remove the table's structure along with all its data"],"answer":2,"explanation":"DELETE is a DML command that may take a WHERE clause; TRUNCATE is a DDL command that removes all rows at once and keeps the table definition. Only DROP removes the structure.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-385","question":"In which order does a database logically process the clauses of a SELECT statement?","options":["SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY","FROM → GROUP BY → WHERE → HAVING → SELECT → ORDER BY","FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","FROM → WHERE → HAVING → GROUP BY → ORDER BY → SELECT"],"answer":2,"explanation":"Rows are taken FROM the tables, filtered by WHERE, grouped, filtered as groups by HAVING, then the SELECT list is computed and finally sorted. That is why WHERE cannot use aggregates but HAVING can.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-386","question":"The condition WHERE Salary BETWEEN 20000 AND 30000 selects rows whose salary is:","options":["From 20000 to 30000, including both 20000 and 30000","Above 20000 and below 30000, excluding both limits","From 20000 up to but not including 30000","Above 20000 and up to and including 30000"],"answer":0,"explanation":"BETWEEN is inclusive at both ends: it means Salary >= 20000 AND Salary <= 30000.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-387","question":"A query must list the customers who have no phone number recorded (the Phone column is NULL). Which condition works?","options":["WHERE Phone = NULL","WHERE Phone = ''","WHERE Phone IS NULL","WHERE Phone = 0"],"answer":2,"explanation":"Any comparison with NULL using = yields UNKNOWN, so 'Phone = NULL' returns no rows; IS NULL is the correct test. An empty string or 0 is a real value, not NULL.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-388","question":"A City column holds Delhi, Pune, Delhi, NULL, Pune, NULL in six rows. What does SELECT COUNT(DISTINCT City) return?","options":["3","4","6","2"],"answer":3,"explanation":"COUNT ignores NULLs, and DISTINCT keeps one copy of each value, leaving Delhi and Pune: 2. Counting NULL as a value gives 3; COUNT(City) would give 4.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-389","question":"A transaction runs: INSERT row 1; SAVEPOINT s1; INSERT row 2; ROLLBACK TO s1; COMMIT. Which of the inserted rows are in the table afterwards?","options":["Row 1 only","Row 2 only","Both row 1 and row 2","Neither row"],"answer":0,"explanation":"ROLLBACK TO s1 undoes only the work done after the savepoint (row 2); row 1 stays, and COMMIT makes it permanent. A plain ROLLBACK would have undone both.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-390","question":"A transfer debits Account A, but the system crashes before Account B is credited. On restart, the debit is undone, so it is as if the transfer never began. Which ACID property is at work?","options":["Consistency","Atomicity","Isolation","Durability"],"answer":1,"explanation":"Atomicity means a transaction happens completely or not at all, so a half-done transfer is rolled back. Durability concerns committed work surviving a crash.","difficulty":"hard","source":"IBPS SO IT Officer · IBPS PO Mains"},
  {"id":"comp-awareness-391","question":"Two transactions run at the same time on the same accounts, yet the final result is the same as if one had run fully before the other. Which ACID property ensures this?","options":["Atomicity","Durability","Consistency","Isolation"],"answer":3,"explanation":"Isolation makes concurrent transactions behave as though they ran one after another (serially), so neither sees the other's half-finished changes.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-392","question":"A database stores records as a tree in which every child record has exactly one parent, as in a company → department → employee chart. Which data model is this?","options":["Hierarchical model","Network model","Relational model","Object-oriented model"],"answer":0,"explanation":"The hierarchical model allows one parent per child. The network model allows a record many parents, and the relational model uses tables linked by keys.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-393","question":"In the three-schema (ANSI/SPARC) architecture, the part of the database that one user group sees, such as the loan officers' view, is defined at the:","options":["Internal level","Conceptual level","Physical level","External level"],"answer":3,"explanation":"The external level holds the individual user views; the conceptual level describes the whole database's logical structure; the internal (physical) level describes storage.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-394","question":"A table has 8 columns and 120 rows. What are its degree and its cardinality?","options":["Degree 120, cardinality 8","Degree 8, cardinality 960","Degree 8, cardinality 120","Degree 128, cardinality 8"],"answer":2,"explanation":"Degree is the number of attributes (columns) and cardinality is the number of tuples (rows): 8 and 120.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-395","question":"Which relational algebra operation picks out chosen COLUMNS of a relation and removes any duplicate rows that result?","options":["Selection (σ)","Projection (π)","Cartesian product (×)","Union (∪)"],"answer":1,"explanation":"Projection keeps the listed attributes, and since a relation is a set, duplicate tuples disappear. Selection picks rows that satisfy a condition.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-396","question":"A data warehouse, unlike a bank's day-to-day transaction database, is mainly designed for:","options":["Recording thousands of small deposits and withdrawals each second","Analysing large volumes of historical data for reports and decisions","Storing user passwords securely in encrypted form","Running the operating system's file and memory management"],"answer":1,"explanation":"A warehouse collects historical data from many sources for analysis (OLAP). Many small live transactions are the job of an OLTP database.","difficulty":"moderate","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-397","question":"Which statement about a view in SQL is correct?","options":["It is a physical copy of a table, refreshed once a day","It is an index that makes searches on a column faster","It is a backup of the table kept in a separate file","It is a stored query that appears to users as a virtual table"],"answer":3,"explanation":"A view stores the SELECT, not the data; each use runs the query on the base tables. Views can hide columns and simplify complex joins for users.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-398","question":"A bank wants a log entry to be written automatically whenever a row in the ACCOUNTS table is updated, without the application doing it. Which database object does this?","options":["A view","An index","A trigger","A cursor"],"answer":2,"explanation":"A trigger is code the DBMS runs automatically on an INSERT, UPDATE or DELETE event. A cursor steps through query results one row at a time.","difficulty":"moderate","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-399","question":"ORDERS.CustomerID is a foreign key to CUSTOMER, declared with ON DELETE CASCADE. What happens when a customer row is deleted?","options":["The delete is refused while any order for that customer exists","The customer's orders are deleted automatically along with it","The CustomerID in that customer's orders is set to NULL","The orders are kept unchanged and point to a missing customer"],"answer":1,"explanation":"CASCADE propagates the delete to the referencing rows. Refusing the delete is the default (RESTRICT/NO ACTION) and setting NULL is ON DELETE SET NULL.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-400","question":"In ENROLMENT(StudentID, CourseID, Grade), a student takes many courses and a course has many students, but a student takes a course only once. What is the primary key?","options":["StudentID on its own","CourseID on its own","The pair (StudentID, Grade)","The pair (StudentID, CourseID)"],"answer":3,"explanation":"Neither ID alone is unique, since both repeat; together they identify one enrolment. A key made of two or more attributes is a composite key.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-401","question":"Which pairing of computer generation and its key technology is WRONG?","options":["Fourth generation – artificial intelligence as its basic technology","First generation – vacuum tubes and machine language","Second generation – transistors and assembly language","Third generation – integrated circuits and operating systems"],"answer":0,"explanation":"The fourth generation is defined by the VLSI microprocessor; artificial intelligence is the aim of the fifth generation. The other three pairings are correct.","difficulty":"very-hard","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-awareness-402","question":"ENIAC, completed in 1945 to compute artillery firing tables, was built with which technology and which number system?","options":["Vacuum tubes; it worked in binary","Vacuum tubes; it worked in decimal","Transistors; it worked in binary","Electromechanical relays; it worked in decimal"],"answer":1,"explanation":"ENIAC used about 18,000 vacuum tubes and did decimal arithmetic with ten-position ring counters; binary stored-program designs such as EDVAC came after it.","difficulty":"very-hard","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-403","question":"The 'stored-program' concept, in which a computer's instructions are kept in the same memory as its data, is chiefly associated with:","options":["Charles Babbage","Herman Hollerith","Blaise Pascal","John von Neumann"],"answer":3,"explanation":"Von Neumann's 1945 EDVAC report set out the stored-program design that most computers still follow. Babbage designed the Analytical Engine, and Hollerith built punched-card tabulators.","difficulty":"moderate","source":"SSC CGL · SBI Clerk Mains"},
  {"id":"comp-awareness-404","question":"Herman Hollerith's punched-card tabulating machine, whose company later grew into IBM, was first used on a large scale for:","options":["The 1890 United States census","Breaking German codes in the Second World War","Calculating artillery tables in 1945","Controlling the patterns on weaving looms"],"answer":0,"explanation":"Hollerith's machines processed the 1890 US census far faster than hand counting. Punched cards for looms came earlier from Jacquard, and code-breaking was the work of machines such as Colossus.","difficulty":"hard","source":"SSC CGL · SBI Clerk Mains"},
  {"id":"comp-awareness-405","question":"Which early mechanical calculator could multiply, by repeated addition using a stepped drum, and not just add and subtract?","options":["Pascal's Pascaline adding machine","Napier's bones multiplying rods","Leibniz's Stepped Reckoner","The Chinese abacus"],"answer":2,"explanation":"Leibniz's Stepped Reckoner (late 1600s) added a stepped drum for multiplication and division. The Pascaline only added and subtracted, and Napier's bones were rods for manual multiplication.","difficulty":"hard","source":"SSC CGL · SBI Clerk Mains"},
  {"id":"comp-awareness-406","question":"Who is regarded as the first computer programmer for her notes containing an algorithm for Charles Babbage's Analytical Engine?","options":["Ada Lovelace","Grace Hopper","Mary Somerville","Hedy Lamarr"],"answer":0,"explanation":"Ada Lovelace published an algorithm to compute Bernoulli numbers on the Analytical Engine in 1843. Grace Hopper came a century later and developed early compilers.","difficulty":"moderate","source":"SSC CGL · SBI Clerk Mains"},
  {"id":"comp-awareness-407","question":"The Intel 4004 of 1971, the first commercially sold single-chip microprocessor, processed data in units of how many bits?","options":["8 bits","16 bits","4 bits","32 bits"],"answer":2,"explanation":"The 4004 was a 4-bit processor designed for a calculator; the 8-bit 8008 and 8080 followed it.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk Mains"},
  {"id":"comp-awareness-408","question":"The Turing Test, proposed by Alan Turing in 1950, checks whether:","options":["A program always halts on every possible input","A machine solves any problem a human can solve faster","A machine's replies in conversation cannot be told apart from a human's","A computer can be built from a tape, a head and a table of rules"],"answer":2,"explanation":"In the 'imitation game' a judge chats by text; if the judge cannot reliably tell the machine from a human, it passes. The tape-and-head model is the Turing machine, and halting is a separate problem.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains"},
  {"id":"comp-awareness-409","question":"SQL, in which a user states what data is wanted rather than how to fetch it step by step, is usually classed as which generation of programming language?","options":["Second generation (2GL)","Third generation (3GL)","Fifth generation (5GL)","Fourth generation (4GL)"],"answer":3,"explanation":"1GL is machine code, 2GL assembly, 3GL procedural languages such as C, and 4GL non-procedural languages such as SQL. 5GL describes logic languages like Prolog.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-410","question":"Prolog, long used in artificial intelligence, is an example of which programming style?","options":["Logic programming, based on facts and rules","Procedural programming, based on step-by-step commands","Assembly programming, based on processor mnemonics","Markup, based on tags that describe document layout"],"answer":0,"explanation":"A Prolog program states facts and rules, and the system infers answers to queries. It is not procedural like C, and markup languages like HTML are not programming languages at all.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-411","question":"A compiler translates a C source file. What is its output called, before the linker combines it with library code?","options":["Executable code","Object code","Byte code","Source code"],"answer":1,"explanation":"The compiler produces object code, machine code with unresolved references; the linker joins object files and libraries into an executable. Byte code is the output of compilers for virtual machines such as Java's.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-412","question":"Match the flowchart symbol with its use: 1. Diamond 2. Parallelogram 3. Oval 4. Rectangle; a. Start or end b. Processing step c. Decision d. Input or output","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-a, 3-d, 4-b"],"answer":0,"explanation":"A diamond holds a yes/no decision, a parallelogram input or output, an oval (terminal) the start or end, and a rectangle a processing step.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-awareness-413","question":"A company modifies a program released under the GNU GPL and distributes the modified version to customers. What does the GPL require?","options":["It must pay the original authors a royalty on every copy sold","It must make the modified source code available under the GPL too","It may keep its changes secret as long as it credits the authors","It may distribute only the compiled program, never the source"],"answer":1,"explanation":"The GPL is a 'copyleft' licence: anyone who distributes a modified version must release its source under the same terms. It does not require royalties; selling copies is allowed.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-414","question":"Software that is stored permanently in a device's ROM or flash memory and directly controls its hardware, such as the BIOS or a router's control program, is called:","options":["Firmware","Middleware","Shareware","Freeware"],"answer":0,"explanation":"Firmware sits between hardware and higher software and survives power-off. Middleware connects applications; shareware and freeware are distribution models.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-415","question":"Which of these is utility software rather than application software?","options":["A spreadsheet program","A disk defragmenter","A web browser","A presentation program"],"answer":1,"explanation":"Utilities maintain and tune the computer itself, such as defragmenters, backup tools and antivirus. Spreadsheets, browsers and presentation programs do the user's own tasks.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-awareness-416","question":"Which single logic gate can act as a 1-bit equality comparator, giving 1 exactly when its two inputs are the same?","options":["XOR","NAND","XNOR","OR"],"answer":2,"explanation":"XNOR outputs 1 for inputs 00 and 11 and 0 otherwise, so it signals equality. XOR does the opposite, signalling a difference.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-417","question":"How is a full adder usually built from half adders?","options":["Two half adders, with their carry outputs joined by an AND gate","Three half adders, with no extra gate needed","Two half adders, with their carry outputs joined by an OR gate","One half adder with an extra XOR gate on its carry output"],"answer":2,"explanation":"The first half adder adds A and B, the second adds that sum to Cin; the final carry is 1 if either half adder produced a carry, so the two carries go through an OR gate.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-418","question":"A 32-to-1 multiplexer must be built using only 8-to-1 multiplexers. What is the least number of 8-to-1 multiplexers needed?","options":["4","6","8","5"],"answer":3,"explanation":"Four 8-to-1 units take the 32 inputs and give 4 outputs; one more 8-to-1 unit (using 4 of its inputs) selects among them, so 5 in all, controlled by 5 select lines.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-419","question":"In which flip-flop is the input combination 1, 1 not allowed, because it leaves the outputs in an invalid state?","options":["JK flip-flop","D flip-flop","T flip-flop","SR flip-flop"],"answer":3,"explanation":"Setting S = R = 1 on an SR flip-flop forces both outputs to the same value, which is forbidden. The JK flip-flop turns 1, 1 into a toggle instead.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-420","question":"How many different Boolean functions of two input variables are possible?","options":["4","16","8","256"],"answer":1,"explanation":"Two inputs give 2² = 4 truth-table rows, and each row's output can be 0 or 1, so there are 2⁴ = 16 functions. 4 counts only the rows, and 256 is the count for three inputs' 8 rows.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-421","question":"The Boolean expression (A + B)(A + C) simplifies to:","options":["A + BC","AB + AC","A + B + C","AB + C"],"answer":0,"explanation":"Expanding gives A·A + A·C + A·B + B·C = A(1 + C + B) + BC = A + BC. This is the distributive law of OR over AND, which has no counterpart in ordinary algebra.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-422","question":"A NOR gate has a signal A on one input and its complement A′ on the other. What is the output?","options":["Always 0","Always 1","Equal to A","Equal to NOT A"],"answer":0,"explanation":"A + A′ is always 1, so its NOR, the complement, is always 0, whatever A is.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-423","question":"In a 4-variable Karnaugh map, a valid group of 8 adjacent 1s gives a product term with how many literals?","options":["3","2","8","1"],"answer":3,"explanation":"A group of 2ᵏ cells removes k variables; 8 = 2³ removes 3 of the 4, leaving a single literal. A group of 4 would leave 2 literals.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-424","question":"An ICU machine measures continuous signals such as heartbeat and blood pressure and converts them into numbers for digital processing and display. What kind of computer is it?","options":["Analog computer","Digital computer","Hybrid computer","Mainframe computer"],"answer":2,"explanation":"It takes analog inputs and processes them digitally, combining both kinds of computer. A purely analog or purely digital machine would do only one of these.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-awareness-425","question":"A large bank's central computer supports thousands of terminals and processes millions of transactions a day with very high reliability. It is best classed as a:","options":["Supercomputer","Minicomputer","Workstation","Mainframe"],"answer":3,"explanation":"Mainframes are built for huge volumes of simultaneous transactions and users. Supercomputers are built for raw calculation speed on scientific problems, not transaction processing.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-426","question":"In a pipelined processor, an instruction needs the result of the instruction just ahead of it, but that result has not yet been written back. What kind of hazard is this?","options":["Structural hazard","Control hazard","Data hazard","Cache-miss penalty"],"answer":2,"explanation":"A data hazard arises when an instruction depends on a result still in the pipeline; forwarding or stalls fix it. Structural hazards are clashes over hardware, and control hazards come from branches.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-427","question":"What value does the MS Excel formula =2+3*2^2 return?","options":["20","14","100","38"],"answer":1,"explanation":"Excel applies ^ first, then *, then +: 2^2 = 4, 3 × 4 = 12, 2 + 12 = 14. Working left to right gives (2 + 3) × 2² = 20.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-428","question":"A disk spins at 6000 rpm and every track holds 500 equal sectors. Ignoring seek time and rotational delay, how long does it take to read one sector as it passes under the head?","options":["20 µs","10 ms","5 ms","2 µs"],"answer":0,"explanation":"6000 rpm = 100 rotations per second, so one rotation takes 10 ms; one sector passes in 10 ms ÷ 500 = 0.02 ms = 20 µs. 5 ms is the average rotational latency, a different delay.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-429","question":"A system uses 16-bit virtual addresses and a page size of 1 KB. How many pages does the virtual address space have, and how many bits form the page offset?","options":["1024 pages, 6-bit offset","16 pages, 10-bit offset","64 pages, 6-bit offset","64 pages, 10-bit offset"],"answer":3,"explanation":"1 KB = 2¹⁰ bytes needs a 10-bit offset, leaving 16 − 10 = 6 bits for the page number, so 2⁶ = 64 pages.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-430","question":"Match the MS Excel error value with its usual cause: 1. #DIV/0! 2. #N/A 3. #REF! 4. #NAME?; a. A lookup value was not found b. The formula refers to a deleted cell c. A function name is misspelt d. A number is divided by zero or an empty cell","options":["1-d, 2-b, 3-a, 4-c","1-d, 2-a, 3-b, 4-c","1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b"],"answer":1,"explanation":"#DIV/0! comes from division by zero, #N/A from a lookup that finds nothing, #REF! from an invalid (often deleted) reference, and #NAME? from text Excel does not recognise, such as =SUMM(A1:A3).","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-431","question":"A company holds the block 172.16.0.0/16 and splits it into equal subnets that must each hold at least 500 hosts. At most how many such subnets can it make?","options":["64","256","512","128"],"answer":3,"explanation":"500 hosts need 9 host bits (2⁹ − 2 = 510), so each subnet is a /23. That leaves 23 − 16 = 7 subnet bits, giving 2⁷ = 128 subnets. 8 host bits allow only 254 hosts.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-432","question":"In MS Excel, which entry puts today's date into a cell as a FIXED value that will not change tomorrow?","options":["Typing the formula =TODAY()","Pressing Ctrl + ;","Pressing Ctrl + Shift + ;","Pressing Ctrl + D"],"answer":1,"explanation":"Ctrl + ; types the current date as a constant. =TODAY() recalculates every day, Ctrl + Shift + ; inserts the current time, and Ctrl + D fills down.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-433","question":"Match the MS Word shortcut with the paragraph alignment it applies: 1. Ctrl + E 2. Ctrl + J 3. Ctrl + L 4. Ctrl + R; a. Right b. Centre c. Left d. Justify","options":["1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-d, 4-a","1-b, 2-d, 3-a, 4-c"],"answer":0,"explanation":"Ctrl + E centres (C is taken by Copy), Ctrl + J justifies, Ctrl + L aligns left and Ctrl + R aligns right.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-434","question":"A branch must print a personalised letter for each of 500 customers whose names and addresses are stored in an Excel sheet. Which MS Word feature does this?","options":["Track Changes","Mail Merge","Macros","Find and Replace"],"answer":1,"explanation":"Mail Merge combines one main document with a data source and produces one copy per record, filling in each customer's fields.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-435","question":"A server’s two 1 TB disks are set up as RAID 1. How much usable space results, and what does this arrangement provide?","options":["2 TB, with blocks striped across both disks for speed","2 TB, with parity blocks spread over both disks","1 TB, with blocks striped across both disks for speed","1 TB, with every block mirrored on both disks"],"answer":3,"explanation":"RAID 1 mirrors the disks, so either one can fail without data loss, but usable space is that of one disk. Striping for speed with no redundancy is RAID 0.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-436","question":"Why does defragmenting a solid-state drive (SSD) give little or no speed benefit?","options":["Its controller always stores each file in one contiguous block","It can only be formatted with FAT32, which never fragments","Its controller compresses every file, so fragments disappear","It has no moving head, so access time does not depend on position"],"answer":3,"explanation":"Defragmenting helps hard disks by cutting seek and rotation delays; an SSD reads any block equally fast, and extra rewrites only add wear. SSD files can still be fragmented.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-437","question":"A 40-slide PowerPoint presentation needs every slide title changed to a new font in one step. What should be edited?","options":["The Slide Master","The Notes Page","The Slide Sorter view","The Handout Master"],"answer":0,"explanation":"Formatting set on the Slide Master flows to every slide based on its layouts. Slide Sorter only rearranges slides, and the Notes and Handout masters affect printouts.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-438","question":"In MS Excel, =VLOOKUP(A2, D2:F100, 3) is entered with NO fourth argument. How does it search?","options":["Exact match only, returning #N/A if A2 is missing","Approximate match, which needs column D to be sorted in ascending order","Exact match, but ignoring the difference between capitals and small letters","Approximate match, which needs column F to be sorted in descending order"],"answer":1,"explanation":"Leaving out range_lookup means TRUE, an approximate match that assumes the first column of the table is sorted ascending; unsorted data can give silently wrong results. Use FALSE for an exact match.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-439","question":"The 32-bit value 0x12345678 is stored starting at address 100 on a little-endian machine. Which byte is at address 100?","options":["78","12","34","56"],"answer":0,"explanation":"Little-endian stores the least significant byte at the lowest address, so 78 sits at 100, then 56, 34 and 12. A big-endian machine would put 12 at address 100.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-440","question":"A 4-way set-associative cache has 256 lines in total. How many sets does it have, and how many address bits select the set?","options":["256 sets, 8 index bits","64 sets, 6 index bits","4 sets, 2 index bits","64 sets, 8 index bits"],"answer":1,"explanation":"Each set holds 4 lines, so 256 ÷ 4 = 64 sets, chosen by log₂ 64 = 6 index bits. 256 sets would be a direct-mapped cache.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-441","question":"In which pair is the expansion of the abbreviation WRONG?","options":["VLSI – Very Large Scale Integration","EEPROM – Electrically Erasable Programmable Read-Only Memory","ALU – Arithmetic Logic Unit","CMOS – Central Memory Operating System"],"answer":3,"explanation":"CMOS stands for Complementary Metal-Oxide Semiconductor, the chip technology used for the small settings memory on a motherboard. The other three expansions are correct.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-442","question":"Which abbreviation is expanded CORRECTLY?","options":["DSL – Data Subscriber Link over Copper Wire","VoIP – Video over Internet Protocol","ISDN – Integrated Services Digital Network","NIC – Network Internet Controller"],"answer":2,"explanation":"ISDN is Integrated Services Digital Network. DSL is Digital Subscriber Line, VoIP is Voice over Internet Protocol, and NIC is Network Interface Card.","difficulty":"very-hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-443","question":"How many of these expansions are correct? I. RAM – Random Access Memory II. CD-R – Compact Disc Recordable III. DPI – Dots Per Inch IV. RPM – Revolutions Per Memory","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are right. RPM is Revolutions Per Minute, the unit for a hard disk's spindle speed.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-444","question":"A fintech's developers upload their code, and the cloud provider supplies and manages the servers, operating system, runtime and database. Which service model is this?","options":["Infrastructure as a Service","Software as a Service","Platform as a Service","Network as a Service"],"answer":2,"explanation":"PaaS gives a ready platform to deploy code without managing servers or the OS. IaaS would leave the OS and runtime to the customer, and SaaS delivers a finished application.","difficulty":"hard","source":"IBPS SO IT Officer · IBPS PO Mains"},
  {"id":"comp-awareness-445","question":"Several banks with the same regulatory and security needs share one cloud infrastructure that is closed to the general public. Which deployment model is this?","options":["Community cloud","Public cloud","Private cloud","Hybrid cloud"],"answer":0,"explanation":"A community cloud serves a group of organisations with shared concerns. A private cloud serves a single organisation, and a hybrid cloud mixes private and public clouds.","difficulty":"hard","source":"IBPS SO IT Officer · IBPS PO Mains"},
  {"id":"comp-awareness-446","question":"Which HTML tag creates a clickable hyperlink to another page?","options":["<link>","<href>","<a>","<hl>"],"answer":2,"explanation":"The anchor tag <a href='…'> makes a hyperlink. <link> connects resources such as stylesheets in the head, and href is an attribute, not a tag.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-447","question":"Clearing a web browser's cache mainly removes:","options":["Stored copies of pages and images kept to load sites faster","The list of websites saved as bookmarks or favourites","The browser's installed extensions and add-ons","Passwords saved in the operating system's key store"],"answer":0,"explanation":"The cache holds local copies of web content so repeat visits load faster; clearing it forces fresh downloads. Bookmarks and extensions are kept separately.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-448","question":"In e-mail, which action sends the original message's attachments along to a new recipient by default?","options":["Reply","Reply All","Forward","Adding the person in CC of the reply"],"answer":2,"explanation":"Forward includes the original attachments; Reply and Reply All normally drop them, since the sender already has them.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-449","question":"Four 2 TB disks are combined in RAID 5. What is the usable storage capacity?","options":["8 TB","4 TB","6 TB","2 TB"],"answer":2,"explanation":"RAID 5 spreads parity over all disks, using the space of one disk for it: (4 − 1) × 2 TB = 6 TB, and any single disk can fail without data loss.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-450","question":"In Windows, what does pressing Shift + Delete on a selected file do?","options":["Moves the file to the Recycle Bin so it can be restored later","Deletes the file at once, without sending it to the Recycle Bin","Hides the file from view in File Explorer without deleting it","Deletes only the file's shortcut, leaving the file"],"answer":1,"explanation":"Shift + Delete bypasses the Recycle Bin (after a confirmation), so the file cannot be restored from there; plain Delete moves it to the Recycle Bin.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-451","question":"A frame arrives on one port of an ordinary network hub. What does the hub do with it?","options":["Repeats it out of every other port, since it cannot read addresses","Sends it only to the port where the destination MAC address lives","Drops it unless the destination IP address is on the same subnet","Stores it and forwards it after checking the frame for errors"],"answer":0,"explanation":"A hub is a physical-layer multiport repeater: it regenerates the signal to all other ports, so every device shares one collision domain. Forwarding by MAC address is what a switch does.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-452","question":"Which of these link speeds is the FASTEST?","options":["100 MBps","900 Mbps","0.1 GBps","1 Gbps"],"answer":3,"explanation":"A capital B means bytes: 100 MBps = 800 Mbps and 0.1 GBps = 800 Mbps. So 1 Gbps = 1000 Mbps is the fastest, ahead of 900 Mbps.","difficulty":"very-hard","source":"IBPS PO Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-453","question":"A modem sends 2400 symbols per second, and each symbol carries 4 bits (16 signal states). What is its bit rate?","options":["9600 bps","2400 bps","600 bps","38,400 bps"],"answer":0,"explanation":"Bit rate = baud × bits per symbol = 2400 × 4 = 9600 bps; 16 states give log₂ 16 = 4 bits per symbol. Baud and bit rate are equal only for 2-level signalling.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-454","question":"A noiseless channel has a bandwidth of 3000 Hz and uses 4 signal levels. By Nyquist's formula, what is its maximum data rate?","options":["6000 bps","24,000 bps","12,000 bps","3000 bps"],"answer":2,"explanation":"Nyquist: C = 2B log₂ L = 2 × 3000 × log₂ 4 = 2 × 3000 × 2 = 12,000 bps. Dropping the factor 2 gives 6000 bps.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-455","question":"Which error-detecting technique treats the data bits as a polynomial, divides by a fixed generator and appends the remainder, as Ethernet frames do?","options":["Single parity bit","Cyclic redundancy check","Hamming code","Two-dimensional parity"],"answer":1,"explanation":"CRC appends the remainder of polynomial division, and the receiver repeats the division to check it. It catches burst errors far better than parity; Hamming code is mainly for correction.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-456","question":"A frame is sent to the MAC address FF:FF:FF:FF:FF:FF. Which devices accept it?","options":["Only the default router of the LAN","Only the device whose MAC address was looked up last","Every device on the same LAN (broadcast domain)","Every device on the internet that is switched on"],"answer":2,"explanation":"All-ones is the Ethernet broadcast address, accepted by every NIC in the broadcast domain; routers do not forward it beyond the LAN. ARP requests use it.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-457","question":"A PC can reach other computers on its own subnet but nothing outside it, including websites by IP address. Which setting is most likely missing or wrong?","options":["The DNS server address","The default gateway","The MAC address","The subnet's broadcast address"],"answer":1,"explanation":"Traffic for other networks goes to the default gateway (router); without it only local hosts are reachable. A DNS fault would still let sites be reached by IP address.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-458","question":"A bank's employees browse the web through a server that sends requests on their behalf, caches common pages and hides internal addresses from websites. This server is a:","options":["Proxy server","Mail server","DHCP server","File server"],"answer":0,"explanation":"A forward proxy stands between users and the internet, filtering and caching traffic. A DHCP server hands out addresses and a mail server handles e-mail.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-459","question":"Which protocol is used to monitor and manage network devices such as routers, switches and printers, for example to read their traffic counters?","options":["SMTP","SNMP","NTP","ICMP"],"answer":1,"explanation":"Simple Network Management Protocol lets a manager query and configure device agents. SMTP sends mail, NTP synchronises clocks and ICMP carries error and echo messages.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-460","question":"The pair made of an IP address and a port number, such as 192.168.1.5:443, which marks one end of a network connection, is called a:","options":["MAC address","Socket","Subnet","Domain"],"answer":1,"explanation":"A socket is identified by IP address plus port, and a TCP connection by the pair of sockets at its two ends. The port alone picks the application on the host.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-461","question":"The 'well-known' port numbers, reserved for standard services such as HTTP, FTP and DNS, fall in which range?","options":["1024 to 49151","49152 to 65535","0 to 255","0 to 1023"],"answer":3,"explanation":"Well-known ports are 0–1023, registered ports 1024–49151, and dynamic or private ports 49152–65535. Port numbers are 16-bit, so 65535 is the top.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-462","question":"Memory location 2000 holds the value 3000, and location 3000 holds 45. An instruction loads register R1 from address 2000 using INDIRECT addressing. What does R1 receive?","options":["45","3000","2000","2045"],"answer":0,"explanation":"In indirect addressing the instruction's address (2000) holds the address of the operand (3000), so R1 gets memory[3000] = 45. Direct addressing would load 3000, and immediate addressing 2000.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-463","question":"An empty stack receives PUSH 5, PUSH 8, POP, PUSH 3, PUSH 9, POP, POP. What will the NEXT pop return?","options":["8","3","9","5"],"answer":3,"explanation":"After PUSH 5, 8 the POP removes 8; PUSH 3, 9 then two POPs remove 9 and 3, leaving only 5. A stack is last-in, first-out.","difficulty":"very-hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-464","question":"Graphics processors (GPUs) are widely used to train machine-learning models mainly because they:","options":["Run a single instruction stream much faster than any CPU core can","Have thousands of simple cores working on many data items at once","Store the whole training data set permanently in their own memory","Can run training programs without any operating system or driver"],"answer":1,"explanation":"Training is dominated by matrix arithmetic that splits into many identical independent operations, which suits a GPU's massive data parallelism. A single CPU core is faster on one sequential stream.","difficulty":"hard","source":"IBPS SO IT Officer · IBPS PO Mains"},
  {"id":"comp-awareness-465","question":"A hard disk is sold as '500 GB', yet Windows reports its size as about 465 GB. Why?","options":["About 35 GB is hidden for the operating system's recovery files","The maker counts 1 GB as 10⁹ bytes, while Windows divides by 2³⁰","Formatting with NTFS always takes 7% of a disk for the file table","Bad sectors found at the factory are subtracted from the total"],"answer":1,"explanation":"500 × 10⁹ bytes ÷ 2³⁰ (1,073,741,824) ≈ 465.7, which Windows labels GB though it is really GiB. No space is missing; the units differ.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-466","question":"A 4 × 6 inch photograph is scanned at 300 dpi. How many pixels does the scanned image contain?","options":["7,200","21,600","2,160,000","720,000"],"answer":2,"explanation":"4 in × 300 = 1200 pixels and 6 in × 300 = 1800 pixels; 1200 × 1800 = 2,160,000. Multiplying area (24 sq in) by 300 just once gives 7,200.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-awareness-467","question":"How many times larger is the key space of a 128-bit key than that of a 64-bit key?","options":["2 times","64 times","2⁶⁴ times","2¹²⁸ times"],"answer":2,"explanation":"2¹²⁸ ÷ 2⁶⁴ = 2⁶⁴. Every extra key bit doubles the brute-force effort, so doubling the length does far more than double it.","difficulty":"very-hard","source":"IBPS SO IT Officer · IBPS PO Mains"},
  {"id":"comp-awareness-468","question":"SHA-256 hashes are computed for a 1-byte file and a 1 GB file. How long are the two hash values?","options":["Both are exactly 256 bits","1 byte and 1 GB respectively","256 bits and 256 bytes respectively","They vary with the data, about 1% of the file size"],"answer":0,"explanation":"A hash function gives a fixed-length digest whatever the input size: SHA-256 always outputs 256 bits (64 hex characters).","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-469","question":"In a one-address (accumulator-based) machine, what does the instruction ADD X do?","options":["Adds X to itself and stores the result back at address X","Adds the contents of address X to the accumulator, leaving the result there","Adds the number X to the program counter to jump ahead","Adds the accumulator to address X and stores the result at X"],"answer":1,"explanation":"With one explicit address, the accumulator is the implied second operand and destination: ACC ← ACC + M[X].","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-470","question":"A child process has finished running, but its parent has not yet read its exit status, so its entry stays in the process table. Such a process is called:","options":["An orphan process","A daemon process","A zombie process","A blocked process"],"answer":2,"explanation":"A zombie has terminated but keeps a process-table entry until the parent calls wait(). An orphan is a still-running child whose parent has already exited.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-471","question":"Pages are 4 KB (4096 bytes) and a process needs 10,300 bytes. How many pages are allocated, and how much internal fragmentation results?","options":["3 pages; 1988 bytes wasted","2 pages; 2108 bytes wasted","3 pages; 2108 bytes wasted","3 pages; no space wasted"],"answer":0,"explanation":"10,300 ÷ 4096 ≈ 2.5, so 3 pages (12,288 bytes) are needed; the unused part of the last page is 12,288 − 10,300 = 1988 bytes. 2108 is the part of the third page actually used.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-472","question":"A disk head is at cylinder 50, and requests wait for cylinders 82, 170, 43, 140, 24, 16 and 190. Under Shortest Seek Time First, what is the total head movement?","options":["642 cylinders","174 cylinders","240 cylinders","208 cylinders"],"answer":3,"explanation":"SSTF visits 43, 24, 16, 82, 140, 170, 190: 7 + 19 + 8 + 66 + 58 + 30 + 20 = 208. Serving them in arrival order (FCFS) would cost 642.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-473","question":"Table A has 5 rows and table B has 4 rows with the same columns, and exactly 2 rows appear in both; neither table has duplicates of its own. How many rows do A UNION B and A UNION ALL B return?","options":["7 and 9","9 and 7","9 and 9","5 and 4"],"answer":0,"explanation":"UNION removes duplicates: 5 + 4 − 2 = 7 rows. UNION ALL keeps every row: 5 + 4 = 9.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-474","question":"How many bits hold the fraction (mantissa) in IEEE 754 double precision, and about how many significant decimal digits does that give?","options":["23 bits; about 7 digits","52 bits; about 7 digits","64 bits; about 19 digits","52 bits; about 15–16 digits"],"answer":3,"explanation":"Double precision uses 1 sign, 11 exponent and 52 fraction bits; with the hidden bit that is 53 bits ≈ 15–16 decimal digits. 23 bits and about 7 digits describe single precision.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-475","question":"In an ER model, CUSTOMER and ACCOUNT have a one-to-many relationship (one customer, many accounts; each account has one customer). When converted to tables, where does the foreign key go?","options":["In CUSTOMER, holding the account number","In a third table that is required for every relationship","In ACCOUNT, holding the customer's ID","In both tables, each pointing to the other"],"answer":2,"explanation":"The foreign key goes on the 'many' side: each account row stores its one customer's ID. A separate linking table is needed only for many-to-many relationships.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-476","question":"A device joins two LAN segments, learns which MAC addresses sit on each side, and forwards a frame across only when its destination is on the other side. It is a:","options":["Bridge","Repeater","Router","Modem"],"answer":0,"explanation":"A bridge filters frames by MAC address at the data link layer, splitting collision domains; a switch is essentially a many-port bridge. A repeater just regenerates signals, and a router works with IP addresses.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-477","question":"Bank servers must agree on the exact time so that transaction logs and security certificates check correctly. Which protocol keeps their clocks synchronised?","options":["SNMP","NTP","SMTP","ARP"],"answer":1,"explanation":"The Network Time Protocol synchronises clocks across a network, typically to within milliseconds. SNMP manages devices, and ARP maps IP to MAC addresses.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-478","question":"A bank lets selected outside vendors and partner firms log in securely to part of its private internal network to share orders and documents. That arrangement is an:","options":["Intranet","Internet","Extranet","Ethernet"],"answer":2,"explanation":"An extranet extends part of an intranet to authorised outsiders. An intranet is for the organisation's own staff, and Ethernet is a LAN technology.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-479","question":"'Big data' is commonly described by three Vs. Which set is it?","options":["Volume, Velocity and Variety","Value, Visibility and Validity","Volume, Virtualisation and Vision","Velocity, Verification and Version"],"answer":0,"explanation":"Big data means huge Volume, arriving at high Velocity, in great Variety (structured, text, images, logs). Later lists add Veracity and Value, but the original three are these.","difficulty":"hard","source":"IBPS PO Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-480","question":"In a blockchain, every block stores the hash of the block before it. What happens if someone alters a transaction in an old block?","options":["Only that block's timestamp changes, so nobody can notice","The block is automatically encrypted again with a new key","Its hash changes, breaking the link stored in every later block","The transaction is copied to the newest block and accepted"],"answer":2,"explanation":"Changing data changes the block's hash, which no longer matches the previous-hash field in the next block, so the tampering shows unless every later block is redone, which consensus makes infeasible.","difficulty":"hard","source":"IBPS PO Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-481","question":"A bank trains a model on past loan applications, each labelled 'repaid' or 'defaulted', so that it can predict the outcome for new applicants. What kind of machine learning is this?","options":["Unsupervised learning","Reinforcement learning","Clustering","Supervised learning"],"answer":3,"explanation":"Learning from examples that carry known answers (labels) is supervised learning, here a classification task. Unsupervised learning and clustering find patterns in unlabelled data.","difficulty":"hard","source":"IBPS PO Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-482","question":"If the time quantum in Round Robin scheduling is made larger than every process's CPU burst, the algorithm behaves exactly like:","options":["Shortest Job First","Priority scheduling","First-Come, First-Served","Shortest Remaining Time First"],"answer":2,"explanation":"Every process then finishes within its first quantum, in arrival order, with no pre-emption, which is FCFS. A very small quantum instead causes heavy context-switch overhead.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-483","question":"Why are B+ trees preferred for database indexes that must also answer range queries such as 'balance between 10,000 and 50,000'?","options":["They store records in hash buckets, so each lookup takes one step","All records sit in linked, ordered leaves, so a range is read leaf by leaf","They keep every record in the root node, so no disk access is needed","They are unbalanced, so recent keys are found faster than old ones"],"answer":1,"explanation":"A B+ tree keeps data pointers only in leaves, which are chained in key order; after finding the first key, the scan just follows the leaf links. Hash indexes cannot do ranges.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-484","question":"Two parties who have never met want to agree on a shared secret key over an open network that eavesdroppers can watch. Which method is designed for this?","options":["Diffie–Hellman exchange","Caesar shift cipher","SHA-256 hash function","Base64 text encoding"],"answer":0,"explanation":"Diffie–Hellman lets both sides derive the same secret from publicly exchanged values without sending the key itself. Hashing gives no shared secret, and Base64 is not encryption at all.","difficulty":"hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-485","question":"Assertion (A): Virtual memory lets a program larger than the physical RAM run. Reason (R): Only the pages a program currently needs must be in RAM; the rest can stay on disk until used.","options":["A is true but R is false","A is false but R is true","Both A and R are true, but R does not explain A","Both A and R are true, and R explains A"],"answer":3,"explanation":"Demand paging brings in pages only when referenced, which is exactly why a program larger than RAM can run, so R correctly explains A.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains"},
  {"id":"comp-awareness-486","question":"An online platform lets individuals list their used phones and furniture and sell them directly to other individuals. Which e-commerce model is this?","options":["B2B","B2C","C2C","B2G"],"answer":2,"explanation":"Consumer-to-consumer platforms connect private sellers with private buyers; the platform only hosts the listings. B2C is a firm selling to consumers.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-487","question":"What is 0101 − 0111 in 4-bit two's-complement arithmetic?","options":["1110","0010","1010","1101"],"answer":0,"explanation":"Add the two's complement of 0111 (which is 1001): 0101 + 1001 = 1110, which is −2, matching 5 − 7. 0010 is +2, the sign error.","difficulty":"very-hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-488","question":"A device's memory occupies the addresses 0x8000 to 0xBFFF, inclusive, with one byte at each address. How much memory is that?","options":["32 KB","8 KB","48 KB","16 KB"],"answer":3,"explanation":"0xBFFF − 0x8000 + 1 = 0x4000 = 16,384 bytes = 16 KB. Forgetting the +1 gives 16,383, and reading 0xC000 as the size gives 48 KB.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-489","question":"What is the largest 3-digit hexadecimal number minus the largest 3-digit octal number, in decimal?","options":["3584","222","4095","3072"],"answer":0,"explanation":"(FFF)₁₆ = 16³ − 1 = 4095 and (777)₈ = 8³ − 1 = 511, so the difference is 3584. Treating both as decimal gives 999 − 777 = 222.","difficulty":"very-hard","source":"SSC CGL · IBPS SO IT Officer"},
  {"id":"comp-awareness-490","question":"What is 11011011 XOR 10101110?","options":["10001010","01110101","11111111","01110100"],"answer":1,"explanation":"XOR gives 1 where the bits differ: 11011011 ⊕ 10101110 = 01110101. 10001010 is the AND of the two.","difficulty":"very-hard","source":"IBPS SO IT Officer · SSC CGL"},
  {"id":"comp-awareness-491","question":"A program must clear the lowest 4 bits of a byte to 0 while keeping the upper 4 bits unchanged. With which mask, written in hexadecimal, should the byte be ANDed?","options":["0F","FF","00","F0"],"answer":3,"explanation":"AND with 1 keeps a bit and AND with 0 clears it, so the mask is 1111 0000 = F0. ANDing with 0F would keep the low bits and clear the high ones instead.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-492","question":"Which address can be assigned to a host in the subnet 10.0.0.4/30?","options":["10.0.0.4","10.0.0.7","10.0.0.6","10.0.0.8"],"answer":2,"explanation":"A /30 block holds 4 addresses: 10.0.0.4 (network), .5 and .6 (hosts) and .7 (broadcast). 10.0.0.8 begins the next subnet.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-493","question":"Relation R(A, B, C) has the composite key AB and the dependency B → C. What is the highest normal form R satisfies?","options":["1NF","2NF","3NF","BCNF"],"answer":0,"explanation":"C depends on B, only part of the key AB, which is a partial dependency and breaks 2NF. So R is only in 1NF; splitting out (B, C) fixes it.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-494","question":"Each process in memory spends 80% of its time waiting for I/O. With three such independent processes in memory, about what fraction of time is the CPU busy?","options":["20%","51%","60%","49%"],"answer":3,"explanation":"The CPU is idle only when all three wait at once: 0.8³ = 0.512, so utilisation = 1 − 0.512 ≈ 49%. Adding 20% per process gives the trap 60%, and 51% is the idle fraction.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-495","question":"A DBA adds a new column to a table's conceptual schema, and the existing application programs and user views keep working unchanged. This shows:","options":["Logical data independence","Physical data independence","Referential integrity","Data redundancy"],"answer":0,"explanation":"Logical data independence shields the external level from changes to the conceptual (logical) schema. Physical data independence covers changes to storage, such as new indexes.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-496","question":"Arrange in chronological order: 1. Delivery of UNIVAC I 2. Release of the Intel 4004 microprocessor 3. Completion of ENIAC 4. First message sent over ARPANET","options":["3, 4, 1, 2","1, 3, 4, 2","3, 1, 4, 2","3, 1, 2, 4"],"answer":2,"explanation":"ENIAC was completed in 1945, UNIVAC I delivered in 1951, the first ARPANET message sent in 1969 and the Intel 4004 released in 1971.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk Mains"},
  {"id":"comp-awareness-497","question":"Asha sends an e-mail from her laptop's mail client; Ravi, on another provider, reads it on his phone and keeps it synced on the server. Which protocols carry it at each step?","options":["SMTP to her server, SMTP between the servers, IMAP to Ravi's phone","SMTP to her server, IMAP between the servers, POP3 to Ravi's phone","IMAP to her server, SMTP between the servers, SMTP to Ravi's phone","HTTP to her server, POP3 between the servers, IMAP to Ravi's phone"],"answer":0,"explanation":"SMTP pushes mail from client to server and from server to server; the recipient fetches it with IMAP (synced) or POP3. IMAP and POP3 never move mail between servers.","difficulty":"very-hard","source":"SBI Clerk Mains · IBPS SO IT Officer"},
  {"id":"comp-awareness-498","question":"A recursive DNS resolver has nothing cached and must find the IP address of www.example.in. In which order does it query the servers?","options":["Authoritative server for example.in, then .in TLD server, then root server","Root server, then authoritative server for example.in, then .in TLD server","The .in TLD server, then root server, then authoritative server for example.in","Root server, then .in TLD server, then authoritative server for example.in"],"answer":3,"explanation":"The root points to the .in TLD servers, which point to example.in's authoritative server, which gives the final address; each step narrows the name from the right.","difficulty":"very-hard","source":"IBPS SO IT Officer"},
  {"id":"comp-awareness-499","question":"How many of these statements are correct? I. Cache memory is faster than CPU registers. II. SRAM stores each bit in a flip-flop. III. EEPROM can be erased electrically. IV. Virtual memory adds to the physical RAM installed.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are true. Registers are faster than cache (I is false), and virtual memory uses disk to extend the address space without adding physical RAM (IV is false).","difficulty":"very-hard","source":"SBI Clerk Mains · IBPS PO Mains"},
  {"id":"comp-awareness-500","question":"What is (101101)₂ ÷ (101)₂, written in binary?","options":["1011","1101","1001","111"],"answer":2,"explanation":"101101 = 45 and 101 = 5; 45 ÷ 5 = 9 = (1001)₂, with no remainder.","difficulty":"very-hard","source":"SSC CGL · IBPS SO IT Officer"},
];

export default questions;
